const JOURNALS = [
  {"module": 1, "slug": "about-you", "code": "01.01A", "kind": "Journal", "title": "About You", "blurb": "Give me a snapshot of where you are right now. Your work, your relationships, where you live, anything…", "intro": "A snapshot, not a deep dive. Take your time over the first week. Send back to me at least 48 hours before our first session. You've read what this work is. Now I want to hear where you are. This is a snapshot. Where you are in your life right now, what's been hard lately, what you most want to work on.", "sections": [{"heading": "Before you begin", "note": "Take a couple of minutes of breath first. Sit with your eyes closed. Let your body settle. Then open your eyes and begin writing.", "prompts": []}, {"heading": "1. What's bringing you here", "prompts": [{"id": "about-you-1", "kind": "long", "label": "1. What's bringing you here", "text": "Give me a snapshot of where you are right now. Your work, your relationships, where you live, anything significant about this chapter of your life. What's the felt sense of it? Mostly fine? Frayed? Quietly desperate? Just describe it as you'd describe it to a friend. Then say why now. What made you reach out at this point and not three years ago?"}]}, {"heading": "2. What's been bumping into you", "prompts": [{"id": "about-you-2", "kind": "long", "label": "2. What's been bumping into you", "text": "What's been hard lately? The patterns, situations, conversations, or moments that keep tripping you up. Where do you feel stuck, drained, or pulled too thin. Stay in the present. Don't try to explain or fix it. Just describe what's there."}]}, {"heading": "3. Where you see the performance trap showing up", "prompts": [{"id": "about-you-3", "kind": "long", "label": "3. Where you see the performance trap showing up", "text": "In the Welcome, I named three common masks the performance trap wears. Achievement: *if I win, I'll belong.* Care: *if I solve your problems, you won't leave.* Invulnerability: *if I don't need anything, I won't be a burden.* Which one resonates most with how you've been operating lately? It might be one of these. It might be a hybrid. Just name what you notice in your current life. A paragraph or two is plenty. We'll go deeper together in the sessions."}]}, {"heading": "4. Three things you most want to work on", "prompts": [{"id": "about-you-4", "kind": "short", "label": "Pick the three challenges, patterns, or stuck places you mos", "text": "Pick the three challenges, patterns, or stuck places you most want to work with in this program. Be concrete. Not abstract things like \"live more authentically.\" Specific situations, relationships, decisions, or places where you'd like to move differently."}]}, {"heading": "5. How you want me to work with you", "prompts": [{"id": "about-you-5", "kind": "long", "label": "5. How you want me to work with you", "text": "What helps you feel met? Structure, softness, directness, accountability, humor? What shuts you down? If something feels off between us, how do you want to name it? When you hit resistance, how do you want me to meet you in it?"}]}, {"heading": "What happens with this", "note": "This is what I'll be holding when we first meet. Send it back to me at least 48 hours before our first session so I can sit with it and come prepared.", "prompts": []}, {"heading": "Health and wellness", "prompts": [{"id": "about-you-6", "kind": "long", "label": "Health and wellness", "text": "On a scale of one to ten, how satisfied are you with your current health? Are you engaging in regular exercise, maintaining a healthy diet, and getting sufficient sleep to wake up feeling rested?"}]}, {"heading": "The agreements", "prompts": [{"id": "about-you-7", "kind": "agree", "label": "A few things I ask for up front", "text": "A few things I ask for up front. Say yes or no to each one. A no is a real answer and I would rather know now."}, {"id": "about-you-8", "kind": "agree", "label": "Permission to be human", "text": "**Permission to be human.** Just like anyone, I’m bound to make a few mistakes here and there, despite my best intentions. It’s part of being human. Do I have your permission to be human and occasionally err?"}, {"id": "about-you-9", "kind": "agree", "label": "Say so right away", "text": "**Say so right away.** I’m all about making sure you have the best experience possible. But if something doesn’t quite hit the mark or feels a bit off, would you be willing to have a transparent conversation with me right away?"}, {"id": "about-you-10", "kind": "agree", "label": "On time", "text": "**On time.** Would you be on board with making sure to be on time for all our meetings? It really helps everything run smoothly."}, {"id": "about-you-11", "kind": "agree", "label": "Not everything gets solved", "text": "**Not everything gets solved.** Can we agree that while we’re dedicated to helping you overcome challenges, it may not be possible to resolve every single issue within our set time frame? Would you be okay not expecting all your problems to be completely sorted out by the end of this training?"}, {"id": "about-you-12", "kind": "agree", "label": "No big moves for now", "text": "**No big moves for now.** Unless you’ve already got some big plans in motion, could we agree that you’ll hold off on making any life-changing decisions until we wrap up this training? You know, like no rushing into or out of marriages, no quitting your job on a whim, or kicking off a new business venture. Does that sound fair?"}, {"id": "about-you-13", "kind": "agree", "label": "Daily meditation", "text": "**Daily meditation.** Would you commit to daily meditation, starting with 10 to 12 minutes and eventually building up to 30 minutes?"}, {"id": "about-you-14", "kind": "agree", "label": "Come prepared", "text": "**Come prepared.** Could you promise to come prepared for each of our meetings? It’ll make our time together much more productive."}, {"id": "about-you-15", "kind": "agree", "label": "Key points", "text": "**Key points.** If you’ve got stories to tell, could we agree on you giving the key points to keep things concise and save time?"}, {"id": "about-you-16", "kind": "agree", "label": "Being interrupted", "text": "**Being interrupted.** Could we come to an understanding where if I interrupt you or ask you to get to the point, you won’t take it personally? It’s all about keeping our conversation productive."}]}]},
  {"module": 1, "slug": "turning-point", "code": "01.03A", "kind": "Journal", "title": "Turning Point", "blurb": "What is bringing you here? Write about it as concretely as you can. What's the situation? What's been…", "intro": "Best done a few days after reading the Turning Point chapter, so it has time to settle. Not a full life review. Just what has charge for you right now. A few paragraphs per prompt is plenty. Send to me at least 48 hours before our session. I told you about my turning point. The body that wouldn't sleep. The gut that wouldn't quiet. The override that finally stopped working. The Randall session where I finally heard what my body had been trying to tell me for years. Yours will look different. Maybe a marriage in crisis. Maybe a job that no longer fits, or a body that's started to fight back. Maybe a loss that hasn't been metabolized. Or maybe just a creeping sense that something has to give, even though you can't yet name what. This journal is a way of bringing your turning point into focus, listening to what your body is telling you about it, and, if it surfaces on its own, tracing what might be underneath.", "sections": [{"heading": "Before you begin", "note": "Take a few minutes of breath first. Don't think about the prompts yet. Sit with your eyes closed. Let your body settle. When you feel you've arrived, open your eyes and begin writing.", "prompts": []}, {"heading": "1. Your turning point", "prompts": [{"id": "turning-point-1", "kind": "long", "label": "1. Your turning point", "text": "What is bringing you here? Write about it as concretely as you can. What's the situation? What's been changing? What's the thing you keep coming back to in your head, in the shower, when you wake up at 3 a.m.? It might be a single event, or it might be a pattern that's been building for a long time and finally gotten loud enough to notice. Whatever it is, name it."}]}, {"heading": "2. What's happening in your body", "prompts": [{"id": "turning-point-2", "kind": "long", "label": "2. What's happening in your body", "text": "As you sit with that turning point, what's happening in your body right now? Don't go to ideas. Go to sensation. Where do you feel it? In your chest? Your gut? Your throat? Your jaw? Your shoulders? Notice the quality of it. Is it tight, hot, heavy, hollow, restless, numb? Don't try to fix it or make it leave. Just describe it as precisely as you can. Stay with it longer than you usually would. A minute. Two minutes. Let it be there without doing anything about it."}]}, {"heading": "3. If that feeling could speak", "prompts": [{"id": "turning-point-3", "kind": "long", "label": "3. If that feeling could speak", "text": "If the feeling in your body could talk, what might it say? It might be about this exact moment in your life. It might be about something you've been carrying for years that this moment is finally surfacing. It might be both. Don't filter. Don't edit. Write what comes, even if it surprises you. Even if it sounds melodramatic, or unfair, or like something you weren't supposed to admit."}]}, {"heading": "4. If something older surfaced", "prompts": [{"id": "turning-point-4", "kind": "long", "label": "4. If something older surfaced", "text": "If what came up in the previous prompt seems to belong to a longer history than the current situation, follow it down. What role did you learn to play early in your life? Were you the strong one? The funny one? The competent one? The good kid? The peacekeeper? The one who didn't make trouble? The one nobody had to worry about? What were the unspoken terms? What did you have to be in order to stay safe, loved, or simply allowed to stay? *In exchange for connection, safety, love, or belonging in this family, I agree to ____.* If nothing older came up, that's fine. Don't force it. Sometimes the turning point is just about now."}]}, {"heading": "To bring to our session", "prompts": [{"id": "turning-point-5", "kind": "long", "label": "To bring to our session", "text": "Pick one piece of what came up. Whatever feels most alive. The thing you weren't expecting to write, the line that surprised you, the piece that's making you a little nervous to share. That's where we'll begin."}]}]},
  {"module": 1, "slug": "beginners-mind", "code": "01.06A", "kind": "Journal", "title": "Beginner’s Mind", "blurb": "Bring to mind a recent moment that activated something in you. Anger, fear, shame, frustration, hurt. Don't…", "intro": "Best done after a week or so of daily breath practice, when the settling is starting to take hold. Pick one real, recent moment that's been activating. Send to me at least 48 hours before our session. The chapter you just read makes the case for beginner's mind. This journal is where you practice it. The five steps below walk you through applying beginner's mind to one real moment that's been activating in your life. Not as a thought experiment. As an actual inquiry. A note before you begin. This exercise is meant to be done after a breath practice, not before it. The settled state your nervous system arrives at through the straw breath is what makes this work. If you try to do it from inside activation, the mind will just re-confirm what it already believes. From a settled state, it can do something different.", "sections": [{"heading": "Before you begin", "note": "Sit for five to ten minutes of the straw breath, slow and continuous, until you feel the system shift. Shoulders drop. Mind quiets. Body softens. Then open your eyes and begin writing.", "prompts": []}, {"heading": "1. Notice the trigger", "prompts": [{"id": "beginners-mind-1", "kind": "long", "label": "1. Notice the trigger", "text": "Bring to mind a recent moment that activated something in you. Anger, fear, shame, frustration, hurt. Don't analyze it yet. Just let it arise. As it does, turn your attention inward. Where do you feel it in your body? Is your chest tight? Your stomach heavy? Heat in your face or hands? Just notice. No fixing, no judgment. Let the sensation anchor you in the present. Write what you notice. Where it is, what it feels like, how it moves or doesn't."}]}, {"heading": "2. Recognize the story", "prompts": [{"id": "beginners-mind-2", "kind": "long", "label": "2. Recognize the story", "text": "Your mind is already telling a story about that moment. What are you making it mean? Are you assuming someone is judging you, dismissing you, rejecting you, withholding from you? Notice the story without arguing with it. Write it down as plainly as you can. Then ask: does this remind me of something older? A pattern I've carried for years without realizing it? Most of the time, it does. If something older surfaces, write that too."}]}, {"heading": "3. Question the story", "prompts": [{"id": "beginners-mind-3", "kind": "long", "label": "3. Question the story", "text": "Now, gently, question it. Not with fake positivity or forced reframing, but honestly. *Do I know this is true? Do I know it absolutely?* Sit with that question. Let the ground shift under your certainty. There's power in not rushing to an answer. Write whatever surfaces, even if it's just \"I don't know\" or \"I'm not sure anymore.\""}]}, {"heading": "4. Notice what the thought does", "prompts": [{"id": "beginners-mind-4", "kind": "long", "label": "When you believe this thought, when you really sit with the ", "text": "When you believe this thought, when you really sit with the experience of believing it, how do you react? What does it make you feel, do, or avoid? Where does it show up in your body, in your tone of voice, in the way you carry yourself, in the decisions you make? Write down what you notice. Be specific."}, {"id": "beginners-mind-5", "kind": "long", "label": "Then turn the question around", "text": "Then turn the question around. *Who would I be without this thought?* If, even for an hour, you couldn't think it, what would be different? Who shows up in its place? Don't force a tidy answer. Let the question sit. Write what comes."}]}, {"heading": "5. Turn it around", "prompts": [{"id": "beginners-mind-6", "kind": "long", "label": "Take the story you wrote in step 2 and reverse it", "text": "Take the story you wrote in step 2 and reverse it. Write the turnarounds out."}, {"id": "beginners-mind-7", "kind": "long", "label": "If the original was \"He doesn't respect me,\" try:", "text": "If the original was *\"He doesn't respect me,\"* try:"}]}, {"heading": "6. Return to the breath", "prompts": [{"id": "beginners-mind-8", "kind": "long", "label": "6. Return to the breath", "text": "Close the practice with a few more rounds of the straw breath. Notice what has shifted, even subtly. In the body. In the meaning. In the feeling. The shift is the practice. Note what's different now from how you felt at the beginning."}]}, {"heading": "To bring to our session", "prompts": [{"id": "beginners-mind-9", "kind": "long", "label": "To bring to our session", "text": "Pick one piece of what came up. Whatever feels most alive. The trigger, the story, the place a younger pattern surfaced, the alternative reading that surprised you. That's where we'll begin. --- *The inquiry structure in this journal is influenced by Byron Katie's* The Work. *For the full method, see her book* Loving What Is: Four Questions That Can Change Your Life."}]}]},
  {"module": 1, "slug": "follow-up-1", "code": "01.07A", "kind": "Journal", "title": "Follow-Up", "blurb": "What did you notice during our session that felt new or unexpected? Something a part of you hadn't seen…", "intro": "Write what's still alive from our session. The hours right after we meet are when the material is closest to the surface, and getting it on the page keeps it from cooling. Complete within 24 to 48 hours of our session. Don't overthink the answers. Don't let the judging mind get in the way. Just write what's true. Send your responses to me at chad@herstwellness.com when you're done.", "sections": [{"heading": "Before you begin", "note": "Take a couple of minutes of breath first. Sit with your eyes closed. Let your body settle. Then open your eyes and begin writing.", "prompts": []}, {"heading": "1. What felt new or unexpected", "prompts": [{"id": "follow-up-1-1", "kind": "long", "label": "1. What felt new or unexpected", "text": "What did you notice during our session that felt new or unexpected? Something a part of you hadn't seen before, or hadn't been ready to look at directly until now."}]}, {"heading": "2. Assumptions and judgments", "prompts": [{"id": "follow-up-1-2", "kind": "long", "label": "2. Assumptions and judgments", "text": "What assumptions or judgments surfaced for you in the session? Where were you certain about something, and what might it look like to hold that with a bit more curiosity?"}]}, {"heading": "3. Staying with what didn't get fixed", "prompts": [{"id": "follow-up-1-3", "kind": "long", "label": "3. Staying with what didn't get fixed", "text": "There were moments in the session when something hard came up and we didn't move to fix it. What was that like for you? What did you feel happening in your body while you stayed with it?"}]}, {"heading": "4. What opened up", "prompts": [{"id": "follow-up-1-4", "kind": "long", "label": "4. What opened up", "text": "What possibilities or perspectives opened up for you that you hadn't considered before? A different angle, a softer reading, a possibility that didn't seem available before."}]}, {"heading": "5. Meeting what comes next", "prompts": [{"id": "follow-up-1-5", "kind": "long", "label": "5. Meeting what comes next", "text": "What would it look like to meet the next two weeks with curiosity rather than expectation? Where do you feel pulled to perform, and where could you let yourself just notice what arises?"}]}]},
  {"module": 2, "slug": "awareness", "code": "02.02A", "kind": "Journal", "title": "Awareness", "blurb": "Bring to mind a recent moment when you were inside that feeling. Don't explain it yet. Just describe the…", "intro": "This journal is a walk-through, not a series of reflections. It teaches you a sequence of moves you can use any time you're caught inside a difficult feeling. Pick one feeling that's been running you lately and work through the five steps with that one. Plan on 30 to 45 minutes in a quiet hour. Send to me at least 48 hours before our session. The work of this chapter doesn't happen in your head. It happens in the small moments when you stop being identified with a thought or feeling and start being in relationship to it. The five steps below give you the moves that make that possible.", "sections": [{"heading": "Before you begin", "note": "Take a few minutes of breath first. Sit with your eyes closed. Let your body settle. When you feel you've arrived, bring to mind one feeling that's been running you lately. Anxiety, anger, sadness, shame, self-doubt, hopelessness, whatever's been close to the surface. Hold that as you work through what follows.", "prompts": []}, {"heading": "1. Name the moment", "prompts": [{"id": "awareness-1", "kind": "long", "label": "1. Name the moment", "text": "Bring to mind a recent moment when you were inside that feeling. Don't explain it yet. Just describe the moment as it actually happened. What was the situation? What did you feel? What story did your mind start telling about it?"}]}, {"heading": "2. Make the U-turn", "prompts": [{"id": "awareness-2", "kind": "long", "label": "2. Make the U-turn", "text": "Now leave the story alone for a minute and turn your attention to the body. Where does the feeling actually live? In your chest? Your gut? Your throat? Your jaw? Your shoulders? Locate it specifically. Then describe what's there. Its shape. Its temperature. Its weight. Is it sharp or dull? Tight or loose? Moving or still? Does it have a color or a texture? Stay with the sensation, not the story. If your mind tries to wander back to explanation, gently return to the body."}]}, {"heading": "3. Step back an inch", "prompts": [{"id": "awareness-3", "kind": "long", "label": "3. Step back an inch", "text": "Now do something subtle. Mentally step back about an inch from your own body. Not far. Just enough that you can observe the sensation as if you're slightly outside it. From this small distance, what does the feeling look like? Some people describe it as staticky energy, or a heavy stone in the belly, or a tight band across the chest. Yours may be different. Describe it as if you're looking at it instead of being it. Write from the vantage point of an observer."}]}, {"heading": "4. Keep it company", "prompts": [{"id": "awareness-4", "kind": "long", "label": "4. Keep it company", "text": "The default move with a difficult feeling is to fix it, run from it, or try to burn it off. Don't do any of that now. Don't try to make it go away. Instead, surround the sensation with your attention. Breathe with it. Stay close to it the way you would stay close to a friend who's having a hard day. You aren't trying to change it. You aren't analyzing it. You're just keeping it company. Stay there for a minute or two before you write. Then describe what it was like to be with it that way."}]}, {"heading": "5. Try the rephrase", "prompts": [{"id": "awareness-5", "kind": "long", "label": "5. Try the rephrase", "text": "Now come back to the language you started with at the top of the journal. The way you first named the feeling. If you said *I'm anxious*, rewrite it as *there's anxiety here*. If you said *I'm a failure*, rewrite it as *there's self-doubt here*. The move is: take the *I am [X]* statement and turn it into a *there is [X] here* statement. Read both versions out loud. Notice the difference in your body when you say the first versus the second. Write what you notice."}]}, {"heading": "To bring to our session", "prompts": [{"id": "awareness-6", "kind": "long", "label": "To bring to our session", "text": "Pick one piece of what came up. The location of the feeling in your body. The moment you stepped back and could see it. The experience of keeping it company instead of fixing it. The rephrase that landed differently than you expected. That's where we'll begin."}]}]},
  {"module": 2, "slug": "kids-on-the-bus", "code": "02.03A", "kind": "Journal", "title": "Kids on the Bus", "blurb": "Which of the three challenges from About You are you working with here? Write it down again, in your current…", "intro": "Best done a few days after reading the chapter. You'll be working with one of the three challenges you named in About You, looking at how the kids on your bus show up in real situations. We'll do the deeper meeting move in the next chapter. Plan on 30 to 45 minutes. Send to me at least 48 hours before our session. This journal grounds the kids on the bus in your actual life. Instead of trying to identify your parts in the abstract, we'll start with one of the challenges you named at the beginning of this work, look at a specific moment inside it, and tease out which kids got triggered. A note before you begin. The kids who took the wheel in that moment didn't show up randomly. Parts of you take over when some part of you feels unsafe. They're protectors. They come out because they think you need protecting. Keep that in mind as you write.", "sections": [{"heading": "Before you begin", "note": "Re-read what you wrote in **01.01A About You** before you start. Specifically, look at the three challenges you said you most wanted to work on. Pick one of them to work with here. Then take a few minutes of breath. Sit with your eyes closed. Let your body settle. Then open your eyes and begin writing.", "prompts": []}, {"heading": "1. The challenge you're picking", "prompts": [{"id": "kids-on-the-bus-1", "kind": "long", "label": "1. The challenge you're picking", "text": "Which of the three challenges from About You are you working with here? Write it down again, in your current words. What is this challenge, as you'd describe it today?"}]}, {"heading": "2. A specific moment", "prompts": [{"id": "kids-on-the-bus-2", "kind": "long", "label": "2. A specific moment", "text": "Bring to mind a recent moment when this challenge was alive. Something that actually happened, or that's currently happening. Don't generalize. Pick one moment. What was the situation? Who was there? What was being said, or not said? What did you feel? What did you do?"}]}, {"heading": "3. Where was the threat?", "prompts": [{"id": "kids-on-the-bus-3", "kind": "long", "label": "3. Where was the threat?", "text": "Look at that moment again. What made some part of you feel unsafe? Maybe the threat of being judged, dismissed, left, made to feel stupid, found out, not chosen, exposed. Maybe the threat of feeling something you didn't want to feel. Protectors come out when there's perceived threat. The threat doesn't have to be big or obvious. It just has to be enough to register. What was at stake? What did some part of you fear would happen if you let things just be?"}]}, {"heading": "4. Which kid took the wheel?", "prompts": [{"id": "kids-on-the-bus-4", "kind": "long", "label": "4. Which kid took the wheel?", "text": "Now look at how you actually responded in that moment. Which part of you grabbed the wheel? It might have been the fixer, springing into action. The pleaser, smoothing things over. The strong one, going stoic. The angry one, locking down or lashing out. The good kid, making it easy on everyone else. Name the kid. Describe its voice. How did it sound when it took over? What did it say? How did it try to handle the situation?"}]}, {"heading": "5. The inner critic", "prompts": [{"id": "kids-on-the-bus-5", "kind": "long", "label": "5. The inner critic", "text": "Once the kid took the wheel, did the inner critic show up too? It often does, right behind or right alongside. What did your inner critic say? About you, about the situation, about the other people involved? Quote it. Don't soften."}]}, {"heading": "6. What was the kid trying to protect?", "prompts": [{"id": "kids-on-the-bus-6", "kind": "long", "label": "6. What was the kid trying to protect?", "text": "Look at what the kid was actually doing in that moment. What was it trying to keep safe? You don't have to have a complete answer. Just write what you can see. Possibilities to consider. The relationship. Your standing in the room. The version of yourself you've worked hard to maintain. A part of you that has been hurt before and didn't want to be hurt again. The vulnerability of needing something. The kid wasn't there to make your life worse. It was there because, somewhere in your history, taking that exact move kept you safe enough to keep going."}]}, {"heading": "To bring to our session", "prompts": [{"id": "kids-on-the-bus-7", "kind": "long", "label": "To bring to our session", "text": "Pick one piece of what came up. The threat you didn't realize was running underneath the moment. The kid you'd never seen as a kid until now. The inner critic line you don't want to admit was loud. What the kid was actually trying to protect. That's where we'll begin."}]}]},
  {"module": 2, "slug": "meeting-a-part", "code": "02.04A", "kind": "Journal", "title": "Meeting a Part", "blurb": "Which kid are you picking? Name it. Describe it briefly: what it sounds like, what it does, when it usually…", "intro": "Best done a few days after reading the Parts as Protectors chapter, when you've had time to notice your parts moving through the day. You'll be working with one of the kids you identified in the last journal, picking one and walking through a real encounter with it. Plan on 45 to 60 minutes. Send to me at least 48 hours before our session. This journal walks you through the four moves of meeting a part. Pick one kid you can hold steadily in your attention. Stay with that same part through all five prompts. A note on what you're doing here. This isn't about fixing the part or making it leave. It's about having an actual encounter with it. Approaching a part the way you'd approach a scared child or a frantic puppy. The part has been doing a job for a long time. Today, you're going to acknowledge that.", "sections": [{"heading": "Before you begin", "note": "Re-read what you wrote in your Kids on the Bus companion (or your downloaded notes from it). Look at the kids you identified there. Pick one to work with here. Not the easiest one. The one that's been costing you the most. Then take a few minutes of breath. Sit with your eyes closed. Let your body settle. Then open your eyes and begin writing.", "prompts": []}, {"heading": "1. The part you're meeting", "prompts": [{"id": "meeting-a-part-1", "kind": "long", "label": "1. The part you're meeting", "text": "Which kid are you picking? Name it. Describe it briefly: what it sounds like, what it does, when it usually takes the wheel. What's been the cost of having this part run the show?"}]}, {"heading": "2. Unblend", "prompts": [{"id": "meeting-a-part-2", "kind": "long", "label": "2. Unblend", "text": "Shift your language. Instead of *I'm anxious* or *I'm angry* or *I'm a failure*, write the statement as it would sound coming from this part. *The anxious one in me is feeling overwhelmed.* *A part of me is furious about this.* *The inner critic is telling me I'm a failure.* Pick the phrasing that fits your part. Write the same statement two or three times in slightly different ways, until you can hear the difference between you and the part. When you've found the version that creates the most space, note what changed in your body when you said it."}]}, {"heading": "3. Stop resisting", "prompts": [{"id": "meeting-a-part-3", "kind": "long", "label": "3. Stop resisting", "text": "What fight have you been having with this part? How have you been trying to silence it, override it, shame it into being quiet? Write that fight out. Be honest. Now, just for the next few minutes, let the fight go. You don't have to like the part. You don't have to agree with what it's doing. You just have to stop pushing it away. Describe what it's like to not be at war with this part of yourself, even briefly."}]}, {"heading": "4. Who is this part protecting?", "prompts": [{"id": "meeting-a-part-4", "kind": "long", "label": "4. Who is this part protecting?", "text": "This is the deeper question. Underneath the protector is someone the protector is guarding. What younger version of you is this part trying to keep safe? What was that younger you afraid of? What was the threat they couldn't bear to be hurt by? You may know immediately. Or you may have to sit a minute. Either is fine. Once you can sense who's underneath, write about them. What do they look like? How old are they? What do they need that they didn't get? What did the protector start doing to keep them from getting hurt again?"}]}, {"heading": "5. Meet it", "prompts": [{"id": "meeting-a-part-5", "kind": "long", "label": "5. Meet it", "text": "Now write directly to the part. Use its name. Speak to it. Some templates depending on what your part needs. *To a part that needs to be parented:* I see you. I know you're scared. I got you. I'm here now. *To a part that needs to be negotiated with:* I see how hard you've been working. I understand you're trying to keep us safe. I want to make a new agreement with you. (Then state the new terms in the part's own logic. The long game. The bigger picture. Whatever language it speaks.) *To a part that needs to be acknowledged without being acted on:* I see how strong you are. I know you're upset. You're right that this matters. We can feel it without acting on it. Finally, thank it. *Thank you for what you've been doing. I know you've been trying to protect me. The threat you formed around is over now. I can take it from here, with your help, on different terms.* Write your actual encounter with the part. Don't worry about getting it perfect. The point is the contact."}]}, {"heading": "To bring to our session", "prompts": [{"id": "meeting-a-part-6", "kind": "long", "label": "To bring to our session", "text": "Pick one piece of what came up. The younger self you found underneath the part. The thing the part has been protecting against. The moment in the dialogue when something shifted. The version of *thank you* that landed harder than you expected. That's where we'll begin."}]}]},
  {"module": 2, "slug": "session-prep-2", "code": "02.05", "kind": "Session prep", "title": "Session Prep", "blurb": "What's been most alive for you these two weeks? In your work, your relationships, your body. What's been…", "intro": "Do this a day or so before we meet. It's a check-in, not a deep dive, and three or four paragraphs per prompt is plenty. It comes to me automatically, so there's nothing to send. You've had awareness, the kids, and what to do when one of them has the wheel. This is where you land it before we meet. What's been moving, what's been stuck, what's come up in your work with awareness and the parts. I'll start our session from what you put here.", "sections": [{"heading": "Before you begin", "note": "Take a few minutes of breath first. Sit with your eyes closed. Let your body settle. When you've arrived, open your eyes and begin writing.", "prompts": []}, {"heading": "1. What's been alive", "prompts": [{"id": "session-prep-2-1", "kind": "long", "label": "1. What's been alive", "text": "What's been most alive for you these two weeks? In your work, your relationships, your body. What's been pulling at your attention, what's been hard, what's been opening? I don't need a comprehensive update. Just what's close to the surface. And if the honest answer is that not much moved, write that. It's useful to me either way."}]}, {"heading": "2. Which kid has been driving", "prompts": [{"id": "session-prep-2-2", "kind": "long", "label": "2. Which kid has been driving", "text": "Now turn to the module material. Which of the kids on your bus has been showing up most often? When? In what situations? Has the inner critic been loud? Has the fixer been on overdrive? Has a part you didn't expect taken over more than usual? And if you've had a go at meeting one of them on its terms, how did it land? Small attempts count, and so do the ones that went nowhere."}]}, {"heading": "3. What you want to focus on in our session", "prompts": [{"id": "session-prep-2-3", "kind": "long", "label": "3. What you want to focus on in our session", "text": "What's the thing you most want to bring to our session? It can be a specific situation, a pattern you've been bumping into, a part you've been wrestling with, a feeling you can't quite name, or something you'd like to think through out loud. If multiple things are on your mind, name them all. We can decide together where to start."}]}]},
  {"module": 2, "slug": "follow-up-2", "code": "02.05A", "kind": "Journal", "title": "Follow-Up", "blurb": "What from our session is still with you? A specific moment, a shift in your body, something I said that you…", "intro": "Complete within 24 to 48 hours of our session, while what came up is still close to the surface. Send your responses to me at chad@herstwellness.com when you're done. Write what's still alive from our session. The hours right after we meet are when the material is closest to the surface, and getting it on the page keeps it from cooling. Don't overthink the answers. Don't let the judging mind get in the way. Just write what's true.", "sections": [{"heading": "Before you begin", "note": "Take a couple of minutes of breath first. Sit with your eyes closed. Let your body settle. Then open your eyes and begin writing.", "prompts": []}, {"heading": "1. What stayed with you", "prompts": [{"id": "follow-up-2-1", "kind": "long", "label": "1. What stayed with you", "text": "What from our session is still with you? A specific moment, a shift in your body, something I said that you can't quite let go of, a way of seeing something that wasn't available before. Write what's still close to the surface."}]}, {"heading": "2. The part that surfaced", "prompts": [{"id": "follow-up-2-2", "kind": "long", "label": "2. The part that surfaced", "text": "A part of you probably showed up in the session more than others. The inner critic, the fixer, the scared kid, the rabbit, the angry one, whatever yours are. Which one was most active in the room? What did you learn about it that you hadn't seen before?"}]}, {"heading": "3. The tender part underneath", "prompts": [{"id": "follow-up-2-3", "kind": "long", "label": "3. The tender part underneath", "text": "If a younger version of you showed up in the work, sometimes faintly, sometimes vividly, describe them. How old were they? What were they protecting against? What did they need that they didn't get? If nothing surfaced this time, that's fine. Sometimes the younger part stays hidden for a while. Don't force it."}]}, {"heading": "4. A new move", "prompts": [{"id": "follow-up-2-4", "kind": "long", "label": "4. A new move", "text": "What's one move you're carrying forward into the next two weeks? Maybe a specific phrase to use with a part (*I got you*, *what are you trying to protect?*). Maybe a body cue you're going to notice and turn toward. Maybe a fight with a part of yourself you're going to let go of, for now. Just one. Concrete. Something you can actually do this week."}]}, {"heading": "5. What's still unfinished", "prompts": [{"id": "follow-up-2-5", "kind": "long", "label": "5. What's still unfinished", "text": "The work doesn't wrap up in one session. What's still open for you? What didn't get resolved, didn't get said, didn't get to the bottom of? You can name it without needing to fix it."}]}]},
  {"module": 3, "slug": "formation-of-a-reaction", "code": "03.02A", "kind": "Journal", "title": "The Formation of a Reaction", "blurb": "Something recent that set you off. This week if you have one, the last week or two if not. A conversation, an…", "intro": "One sitting. Forty-five minutes or so, a few days after Sankharas, once you've had a chance to catch yourself in one. Five minutes of breath first. This is the one where I have you map your own loop. Paul's ran from a meeting invite to a curled toe to a story about being laid off, and the whole thing inside a second. Yours has the same five parts and they belong to you, not to him. I'm not asking you to fix the loop. I want you to see it once, slowly enough to find where the opening is. The page holds it still. The companion asks you the next question, which a page can't do. Use both. There's no version of this you can fail. If nothing comes, write nothing came. That's an answer.", "sections": [{"heading": "Start where you are", "prompts": [{"id": "formation-of-a-reaction-1", "kind": "long", "label": "Start where you are", "text": "Something recent that set you off. This week if you have one, the last week or two if not. A conversation, an email, a look, a silence, something turning up on your calendar you weren't expecting. I don't want the biggest one. I want the one that's still close. What happened? Where were you, who was there, what got said, in the words it got said in."}]}, {"heading": "What landed", "prompts": [{"id": "formation-of-a-reaction-2", "kind": "short", "label": "What landed", "text": "Strip it back to the thing itself, before it meant anything. A tone. Six words on a screen. A face that didn't do what you expected. Whatever arrived through your senses and nothing more than that."}]}, {"heading": "What your body did", "prompts": [{"id": "formation-of-a-reaction-3", "kind": "short", "label": "What your body did", "text": "Bring the moment back now. Don't replay the whole thing, just let it be here. Then go to your body as it is while you sit with it. The loop that fired then is firing now, smaller, which is the whole reason this works on a page. Where is it? Throat, chest, gut, jaw, shoulders, somewhere else. Find the word for it. Tight, hot, hollow, gripped, thin, buzzing, flat. Then take that word, come back into the body, and see how it responds. Does it capture the whole of it, or is there a better one underneath?"}]}, {"heading": "What your mind made of it", "prompts": [{"id": "formation-of-a-reaction-4", "kind": "long", "label": "What your mind made of it", "text": "Now notice what the mind is doing, right now, while you sit here. It'll be telling you something. Paul's said *I'm being laid off*. Yours might be the same story from the original moment, or a new spin on it, or a story about this journal. Quote it the way you actually hear it."}]}, {"heading": "What you did", "prompts": [{"id": "formation-of-a-reaction-5", "kind": "long", "label": "What you did", "text": "Not what you should have done. What you did. Went quiet. Got sharper. Answered five emails fast. Fixed it for them. Said you were fine. Left the room in your head while your body stayed in the chair. And then the other half of this one. Sitting here now, what's the pull? To close the journal. To check your phone. To eat something. To make a list. The pull now is the same pull as then."}]}, {"heading": "What it cost afterwards", "prompts": [{"id": "formation-of-a-reaction-6", "kind": "long", "label": "What it cost afterwards", "text": "What the mind did with it once the reaction was over. The replay. The drafting of what you should have said. The worst case. The blame, going one way or the other. How long did it have you? What did it take from your day?"}]}, {"heading": "Familiar?", "prompts": [{"id": "formation-of-a-reaction-7", "kind": "long", "label": "Familiar?", "text": "Does this loop visit you often? Might be a situation. Might be one person. Might be a tone of voice. Might be a memory, and might be nothing."}]}, {"heading": "Where the opening was", "prompts": [{"id": "formation-of-a-reaction-8", "kind": "long", "label": "Where the opening was", "text": "Look back at your own five. It's at the second one, where the body had already answered and the story hadn't arrived yet. There's a beat in there, and I find it's longer than people expect. What was happening in you during that beat? Write what you can see now that you had no chance of seeing then."}]}, {"heading": "Bring me one sentence", "prompts": [{"id": "formation-of-a-reaction-9", "kind": "short", "label": "Bring me one sentence", "text": "One line from this page you want in the room when we meet."}]}]},
  {"module": 3, "slug": "be-with", "code": "03.03A", "kind": "Journal", "title": "Be With", "blurb": "One moment with charge still on it. It can be the one you mapped in the last journal, or a fresh one. Either…", "intro": "One sitting, forty-five minutes or so, after you've been sitting with the meditation for a few days. Don't rush it. The whole point is to give the page the time the practice asks for in real life. Five minutes of breath first, the straw breath, five in and seven out. This is the practice, done slowly, in writing. You did the meditation with your eyes closed and it moved at its own speed. The page moves at yours. It'll hold you at each step long enough for something to happen, and it'll keep a record of what did. The page holds it still. The companion asks you the next question, which a page can't do. Use both. There's no version of this you can fail. If nothing comes, write nothing came. That's an answer.", "sections": [{"heading": "Start where you are", "prompts": [{"id": "be-with-1", "kind": "short", "label": "Start where you are", "text": "One moment with charge still on it. It can be the one you mapped in the last journal, or a fresh one. Either works. Two or three sentences, no more. Where you were, what happened, what landed. You're not analyzing it. You're putting it in the room so the rest of this page has something real to work on."}]}, {"heading": "Where it sits in you", "prompts": [{"id": "be-with-2", "kind": "short", "label": "Where it sits in you", "text": "Bring the scene back and let the image arrive. Don't run the whole film. Then drop into your body as it is now. Throat, chest, gut, jaw, shoulders, somewhere else. Find the word for it. Heat, pressure, tightness, a hollow place, a flutter, something heavy, something hard. Then take that word, come back into the body, and see how it responds. Does it capture the whole of it, or is there a better one underneath?"}]}, {"heading": "What you met first", "prompts": [{"id": "be-with-3", "kind": "long", "label": "What you met first", "text": "The first thing is usually the protection, not the tender thing. Look at what you just wrote. Is any of it hard, or guarded? A band of pressure. A clamp. A metal feeling. A wall of bracing. Where exactly is it? If you had to give it a texture, what would it be. Glass, stone, ice, leather, something else. And if it could talk, what would it say? Usually something plain. *I have to handle this. I can't let them see. If I let go I'll fall apart.*"}]}, {"heading": "Three passes", "prompts": [{"id": "be-with-4", "kind": "short", "label": "Small doses", "text": "Small doses. Touch it, let go, come back. Three times, here, on the page."}, {"id": "be-with-5", "kind": "short", "label": "One", "text": "**One.** Put your attention on it for thirty seconds and no longer. Then go somewhere neutral. Your breath, your hands, the sound of the room. Rest there for thirty seconds. Then a sentence or two: what was it like under your attention, and what was it like to leave."}, {"id": "be-with-6", "kind": "short", "label": "Two", "text": "**Two.** Come back to it for another thirty seconds. Notice if anything has moved. Then back to neutral, and rest. A sentence or two."}]}, {"heading": "What's there now", "prompts": [{"id": "be-with-7", "kind": "long", "label": "What's there now", "text": "Scan again. It may have loosened. It may be exactly where it was. It may have got louder for a stretch before it settled. All three are normal, and none of them is a score. If something softened, what's underneath? Often it's more tender than the thing on top of it. An ache, a scared place, a younger you. If nothing moved, say what's still holding, and what it still seems to think it has to do."}]}, {"heading": "The return", "prompts": [{"id": "be-with-8", "kind": "long", "label": "The return", "text": "This is the move the whole practice is for. Whatever you found, the tender place or the younger you or the protector still holding on, turn toward it here and say something to it directly. It doesn't have to be good. The lines that land are usually the ones you'd say to a frightened kid. *I see you. I know this hurts. I'm not going anywhere.* You're being the one who comes back."}]}, {"heading": "Familiar?", "prompts": [{"id": "be-with-9", "kind": "long", "label": "Familiar?", "text": "Does this one visit you often? Might be a situation. Might be a person. Might be a memory, and might be nothing."}]}, {"heading": "Bring me one sentence", "prompts": [{"id": "be-with-10", "kind": "short", "label": "Bring me one sentence", "text": "One line from this page you want in the room when we meet."}]}]},
  {"module": 3, "slug": "session-prep-3", "code": "03.04", "kind": "Session prep", "title": "Session Prep", "blurb": "What's been most alive for you since we last met? In your work, your relationships, your body. What's been…", "intro": "Do this a day or so before we meet. It's a check-in, not a deep dive, and three or four paragraphs per prompt is plenty. It comes to me automatically, so there's nothing to send. The last chapter asked you to stay with what fires, in small doses, over and over. This is where you land the module before we meet. What's been moving, what's been stuck, what's been showing up in your body. I'll start our session from what you put here.", "sections": [{"heading": "Before you begin", "note": "Take a few minutes of breath first. Sit with your eyes closed. Let your body settle. When you've arrived, open your eyes and begin writing.", "prompts": []}, {"heading": "1. What's been alive", "prompts": [{"id": "session-prep-3-1", "kind": "long", "label": "1. What's been alive", "text": "What's been most alive for you since we last met? In your work, your relationships, your body. What's been pulling at your attention, what's been hard, what's been opening? I don't need a comprehensive update. Just what's close to the surface. And if not much moved, write that. It's useful to me either way."}]}, {"heading": "2. The loop you mapped", "prompts": [{"id": "session-prep-3-2", "kind": "long", "label": "2. The loop you mapped", "text": "In **03.02A The Formation of a Reaction** you walked one of your own sankharas end to end. Has it fired again since you put it on the page? Where were you, and what was different about catching it this time, if anything was? If another loop has been louder than the one you mapped, take that one instead. Looking hard at one of them tends to bring another into view."}]}, {"heading": "3. The practice", "prompts": [{"id": "session-prep-3-3", "kind": "long", "label": "3. The practice", "text": "How's Be With landing? The daily sit, the in-the-moment version, the walk-through in the journal. Where does it open and where does it stick? Be specific where you can. *I sat for fifteen minutes and the protector wouldn't move* gives me something to work with. So does *the shield softened on day six and underneath was a younger me*. The texture is what we'll use. And if the practice has been hard to do at all, or you haven't done it, say so. That's information and I'd rather have it than a tidy answer."}]}, {"heading": "4. What you want to focus on in our session", "prompts": [{"id": "session-prep-3-4", "kind": "long", "label": "4. What you want to focus on in our session", "text": "What do you most want to bring? It can be a loop you can't get under, a moment where staying felt impossible, a part you'd like to meet in real time with me there, or something you want to think through out loud. If several things are on your mind, name them all. We'll decide together where to start."}]}]},
  {"module": 3, "slug": "follow-up-3", "code": "03.04A", "kind": "Journal", "title": "Follow-Up", "blurb": "What's still with you from the session. A moment, a shift in your body, something said that you can't quite…", "intro": "Within a day or two of our session, while it's still close to the surface. Twenty minutes. It comes to me automatically, so there's nothing to send. This one is short on purpose. The work is at its most available right after, and it cools fast. I'd rather have three honest lines now than a considered page next week. Don't let the judging part get hold of it. There's no version of this you can fail. If nothing comes, write nothing came. That's an answer.", "sections": [{"heading": "What stayed", "prompts": [{"id": "follow-up-3-1", "kind": "long", "label": "What stayed", "text": "What's still with you from the session. A moment, a shift in your body, something said that you can't quite put down, something you saw from an angle you hadn't had before."}]}, {"heading": "The loop, from here", "prompts": [{"id": "follow-up-3-2", "kind": "long", "label": "The loop, from here", "text": "If a loop of yours came up, what do you see in it now that you couldn't see while you were inside it? It might be the one you mapped on the page. It might be a different one that surfaced while we talked. And if nothing came into focus, say so. I want that too."}]}, {"heading": "The protector, and what was under it", "prompts": [{"id": "follow-up-3-3", "kind": "long", "label": "The protector, and what was under it", "text": "If something hard turned up in your body, a shield or an armor or a bracing, describe it and say what it did. If you didn't get all the way underneath it, name what you sensed was there. The hint of it. The shape of the thing that wasn't available yet. And if a younger you turned up under the protection, who were they. How old, and what were they holding off."}]}, {"heading": "The return", "prompts": [{"id": "follow-up-3-4", "kind": "long", "label": "The return", "text": "If there was a moment where you turned toward the part that needed someone instead of overriding it, what happened in your body. The breath. The shoulders. The thing that let go. If you didn't get there with me sitting there, what gets in the way when you try it alone?"}]}, {"heading": "One move", "prompts": [{"id": "follow-up-3-5", "kind": "long", "label": "One move", "text": "One thing you're carrying out of here. A sentence to say to a part of you when it fires. A signal in your body you're going to turn toward instead of override. The three passes, used in one particular moment of your week that you already know is coming. One. Concrete. Something you can actually do."}]}, {"heading": "What's still open", "prompts": [{"id": "follow-up-3-6", "kind": "long", "label": "What's still open", "text": "I don't finish things in one session. What's unresolved, unsaid, not got to the bottom of? Name it. You don't have to do anything with it."}]}]},
  {"module": 4, "slug": "surfing", "code": "04.03A", "kind": "Journal", "title": "Surfing", "blurb": "Write about a moment when you left yourself to keep a bond intact. Not a dramatic moment. Often a small one.…", "intro": "This journal is structured to span three days. Plan on forty-five to sixty minutes per day. Each day, you'll work with one specific moment from your life and ride the wave it brings up, on the page. Send the completed journal to me at chad@herstwellness.com by 48 hours before our session. Three moments. Three days. Each one points at the ache underneath the performance. We're not looking for the performance itself this time. We're looking for what got buried so the performance could keep running. The book calls the ache the sacred wound. It's the somatic imprint of all the times you traded yourself, your needs, your sense of aliveness, to stay connected. It lives in the body. It shows up as tightness, heaviness, the I'm fine reflex, the constant push to prove. The three prompts below are three distinct doorways to it. You're not writing for anyone but yourself. Be honest. Be specific. Don't explain. Don't justify. Just tell the truth and stay with the body's response to it. After each story, take a break. Don't move on the same day. Sit with the meditation. Walk. Sleep on it. Come back tomorrow for the next one.", "sections": [{"heading": "Before you begin", "note": "Take five minutes of breath. The straw breath, five in, seven out. Let your body settle. When you've arrived, open your eyes and begin. # Day 1. The Moment You Left", "prompts": []}, {"heading": "The story", "prompts": [{"id": "surfing-1", "kind": "long", "label": "The story", "text": "Write about a moment when you left yourself to keep a bond intact. Not a dramatic moment. Often a small one. The room went hard, or got tense, or got cold, and instead of staying inside your own skin and speaking what was true, you went quiet. Or you agreed. Or you laughed it off. Or you made yourself smaller so the other person could stay big. You were physically still in the room. Internally, you'd already left. What was the moment? Who was there? What did the room ask of you that required you to abandon yourself? What was the version of you that disappeared in that moment? A page or two. Don't edit. Just write what's true."}]}, {"heading": "The body now", "prompts": [{"id": "surfing-2", "kind": "long", "label": "The body now", "text": "Close your eyes for a minute and bring the moment back. The room, the person, the way you held your face. Don't replay the whole thing. Just let the image arrive. Now drop your attention into your body. Notice what's happening *right now*, as you sit with the memory. Where is something present? What's the quality of it? Tight, heavy, hollow, hot, cold, sharp, dull, jumpy, frozen?"}]}, {"heading": "Ride the wave", "prompts": [{"id": "surfing-3", "kind": "long", "label": "Ride the wave", "text": "This is the surfing part. You found the sensation. Now stay with it. Set a timer for three minutes. Close your eyes. Bring your attention to where the sensation is in your body. Don't try to change it. Don't analyze it. Don't make it bigger or smaller. Just keep it company. If your mind drifts into the story, gently come back to the sensation. When the timer goes off, write what happened. Did the sensation move? Did it soften? Did it get sharper before it eased? Did a different sensation surface? Did a memory come up? Did anything shift in your breath or your shoulders? If nothing seemed to happen, write that. Sometimes the wave moves below the threshold of what you can notice in three minutes. That's information too."}]}, {"heading": "What surfaced", "prompts": [{"id": "surfing-4", "kind": "long", "label": "What surfaced", "text": "Often, when you ride a wave to its end, something arrives. The part of you that left often shows itself when you finally come back for it. A younger version. A specific age. A feeling that's been waiting a long time to be felt. A line the body wanted to say. What surfaced for you? Don't force it. If nothing's clear, just write what's there."}]}, {"heading": "What's the next move", "prompts": [{"id": "surfing-5", "kind": "short", "label": "What's the next move", "text": "If a concrete next move surfaces, name it here. A small thing. A truth you want to stop swallowing. A moment in your week where you usually leave yourself, that you want to stay for. If no clear next move is there yet, that's fine. Equanimity isn't about producing answers. It's about being available for them when they come. # Day 2. The Trade You Made"}]}, {"heading": "The story", "prompts": [{"id": "surfing-6", "kind": "long", "label": "The story", "text": "You signed a contract long before you had words for it. The unspoken deal said: *to stay connected here, I have to give up X.* What was X for you? For some people it was anger. *I won't be the kid who explodes, because in this house exploding gets you exiled.* For some it was need. *I won't ask for anything, because asking burdens the person I need.* For some it was softness. *I won't be the tender one, because tenderness gets you mocked or used.* For some it was directness. *I won't say what I actually think, because what I actually think makes the room dangerous.* What was your trade? Try to name the original deal as plainly as you can, in one sentence. Then write the story underneath the deal. Where did it get made? Who was the person whose approval or steadiness or presence required it? What did you have to leave behind, in yourself, to keep them?"}]}, {"heading": "The body now", "prompts": [{"id": "surfing-7", "kind": "long", "label": "The body now", "text": "Hold the trade in mind. *I will give up X to stay connected.* Say it to yourself silently. Drop into the body. Where does the trade live now? It's been living in you for years, maybe decades. The body has been honoring this contract every day. Where do you feel it? What does it feel like?"}]}, {"heading": "Ride the wave", "prompts": [{"id": "surfing-8", "kind": "long", "label": "Ride the wave", "text": "Three minutes. Stay with the sensation. Don't change it, don't analyze it, don't escape it. Come back when your mind drifts. When the timer goes off, write what happened."}]}, {"heading": "What surfaced", "prompts": [{"id": "surfing-9", "kind": "long", "label": "What surfaced", "text": "What arrived on the other side of the wave? Often what surfaces here is the part of you that was traded away. The kid who had the anger. The one who had the need. The one who knew the truth and wasn't allowed to say it. If that part of you showed up, describe them. How old were they? What were they trying to protect or express? What did they get told, explicitly or implicitly, about why they had to go away?"}]}, {"heading": "What's the next move", "prompts": [{"id": "surfing-10", "kind": "short", "label": "What's the next move", "text": "# Day 3. The Want You Buried"}]}, {"heading": "The story", "prompts": [{"id": "surfing-11", "kind": "long", "label": "The story", "text": "There was something you wanted that you stopped letting yourself want. A relationship that would actually meet you. A different shape for your career. A creative thing you set down. A version of intimacy you decided wasn't available. A request you stopped making because the few times you made it, you didn't get a yes, and asking again cost more than not asking. The want didn't go away. It's still in your body. Mostly you've stopped noticing it. Occasionally it surfaces and you push it back down. Write about the want. Don't justify why you stopped wanting it. Don't explain why it wasn't realistic. Just name the thing you actually wanted, and what happened when you started letting yourself stop wanting it."}]}, {"heading": "The body now", "prompts": [{"id": "surfing-12", "kind": "long", "label": "The body now", "text": "Bring the want back into the room. Let yourself remember what it felt like when you still wanted it openly. Drop into the body. Where do you feel the want, or the grief of having buried it? Often it's an ache in the chest, a heaviness in the gut, a tightness in the throat. Sometimes it's a specific kind of empty."}]}, {"heading": "Ride the wave", "prompts": [{"id": "surfing-13", "kind": "long", "label": "Ride the wave", "text": "Three minutes. Stay with the sensation. The want is the wave. Let it move. When the timer goes off, write what happened."}]}, {"heading": "What surfaced", "prompts": [{"id": "surfing-14", "kind": "long", "label": "What surfaced", "text": "What arrived on the other side of the wave? The want, when you stop running from it, often turns out to be more specific than you thought. A particular kind of being met. A particular kind of seen. A particular thing the younger you needed and didn't get. If that becomes clear, write it. If a younger version of you surfaced, describe them. What were they reaching for? What did they need from someone who didn't give it?"}]}, {"heading": "What's the next move", "prompts": [{"id": "surfing-15", "kind": "short", "label": "Sometimes the next move with a buried want is to let yoursel", "text": "Sometimes the next move with a buried want is to let yourself want it again, even if you can't have it. Sometimes it's to make a small move toward it in real life. Sometimes it's to grieve the version of it you didn't get and free up the energy that's been guarding the burial site."}, {"id": "surfing-16", "kind": "long", "label": "What's true for yours? One small concrete thing", "text": "What's true for yours? One small concrete thing."}, {"id": "surfing-17", "kind": "long", "label": "After three days of practice on the page, look back at what ", "text": "After three days of practice on the page, look back at what you wrote."}]}]},
  {"module": 4, "slug": "session-prep-4", "code": "04.04", "kind": "Session prep", "title": "Session Prep", "blurb": "What's been most alive for you in the last two weeks? In your work, in your relationships, in your body.…", "intro": "Twenty-four hours before our session. You know the form. The last two weeks with the law of change, surfing, and the Equanimous practice. What's moved, what's stuck, what's been showing up in your body. We'll start from what you bring.", "sections": [{"heading": "Before you begin", "note": "Take a few minutes of breath first. Sit with your eyes closed. Let your body settle. When you've arrived, open your eyes and begin writing.", "prompts": []}, {"heading": "1. What's been alive", "prompts": [{"id": "session-prep-4-1", "kind": "long", "label": "1. What's been alive", "text": "What's been most alive for you in the last two weeks? In your work, in your relationships, in your body. What's been pulling your attention? What's been hard? What's been opening? You don't have to write a comprehensive update. Just what's been close to the surface."}]}, {"heading": "2. A wave you stayed with", "prompts": [{"id": "session-prep-4-2", "kind": "long", "label": "2. A wave you stayed with", "text": "Name one moment in the last two weeks where you actually surfed something instead of bailing. Even a small one. The argument where you didn't reach for the phone. The text that fired the throat clamp, where you sat with it for thirty seconds before answering. The shame spiral where you stayed with the body instead of the story. What happened? What did you notice in the body? What was different about the action that became available on the other side? If no clean example surfaces, name a wave you tried to surf and bailed on. The bailing is information too."}]}, {"heading": "3. The Equanimous practice", "prompts": [{"id": "session-prep-4-3", "kind": "long", "label": "3. The Equanimous practice", "text": "How's the daily sit landing? Where is it opening, where is it sticking? Be specific where you can. *I sat for thirty minutes and the peak knocked me off* is more useful than *it went fine*. So is *I noticed a wave move through on day eight that I didn't expect*. The texture is what we'll work with. If the practice has been hard to do at all, name that. Resistance is information."}]}, {"heading": "4. What you want to focus on in our session", "prompts": [{"id": "session-prep-4-4", "kind": "long", "label": "4. What you want to focus on in our session", "text": "What's the thing you most want to bring to our session? It can be a specific wave you can't surf, a moment when allowing felt impossible, a pattern that's been showing up in your life, an insight that arrived on the other side of something and you want help integrating, or something you want to think through out loud. If multiple things are on your mind, name them all. We can decide together where to start."}]}]},
  {"module": 4, "slug": "follow-up-4", "code": "04.04A", "kind": "Journal", "title": "Follow-Up", "blurb": "What from our session is still with you? A specific moment, a shift in your body, something I said that you…", "intro": "Complete within 24 to 48 hours of our session, while what came up is still close to the surface. Send your responses to me at chad@herstwellness.com when you're done. Write what's still alive from our session. The hours right after we meet are when the material is closest to the surface, and getting it on the page keeps it from cooling. Don't overthink the answers. Don't let the judging mind get in the way. Just write what's true.", "sections": [{"heading": "Before you begin", "note": "Take a couple of minutes of breath first. Sit with your eyes closed. Let your body settle. Then open your eyes and begin writing.", "prompts": []}, {"heading": "1. What stayed with you", "prompts": [{"id": "follow-up-4-1", "kind": "long", "label": "1. What stayed with you", "text": "What from our session is still with you? A specific moment, a shift in your body, something I said that you can't quite let go of, a way of seeing something that wasn't available before. Write what's still close to the surface."}]}, {"heading": "2. The wave you rode", "prompts": [{"id": "follow-up-4-2", "kind": "long", "label": "2. The wave you rode", "text": "Most sessions in Module 4 surface a wave we ride together. Sometimes it's a wave you've been ducking for years. Sometimes it's a new one that surfaces in the session itself. Either way, describe what we found. What was the wave? Where did it live in your body? What happened as you stayed with it? Did it move, soften, get sharper before it eased, change shape?"}]}, {"heading": "3. What arrived on the other side", "prompts": [{"id": "follow-up-4-3", "kind": "long", "label": "3. What arrived on the other side", "text": "If the wave moved through during the session, what arrived afterward? A memory. A sentence. A clear sense of what you actually want. A clarity about what's been happening that you couldn't have reasoned your way to. If we didn't make it all the way through, name what you sensed was on the other side. The shape of it. The hint of it."}]}, {"heading": "4. The mantra", "prompts": [{"id": "follow-up-4-4", "kind": "long", "label": "4. The mantra", "text": "In *The Law of Change* there's a line. *Believe the feelings, not the thoughts.* Was there a moment in the session where you saw that distinction clearly? Where you noticed the body was saying one thing and the mind was telling a different story? What did each say?"}]}, {"heading": "5. A new move", "prompts": [{"id": "follow-up-4-5", "kind": "long", "label": "5. A new move", "text": "What's one move you're carrying forward into the next two weeks? Maybe it's the titration rhythm applied to a specific recurring moment in your week. Maybe it's the *believe the feelings* mantra at the moment of activation. Maybe it's the thirty-second wave practice in a specific situation that always fires. Just one. Concrete. Something you can actually do this week."}]}, {"heading": "6. What's still unfinished", "prompts": [{"id": "follow-up-4-6", "kind": "long", "label": "6. What's still unfinished", "text": "The work doesn't wrap up in one session. What's still open for you from this module? What didn't get resolved, didn't get said, didn't get to the bottom of? You can name it without needing to fix it."}]}]},
  {"module": 5, "slug": "protector-and-wound", "code": "05.03A", "kind": "Journal", "title": "Protector and Wound", "blurb": "Of the protectors named in the chapter (the inner critic, the achiever, the caretaker, the suppressor of…", "intro": "This journal is structured to span three days. Plan on forty-five to sixty minutes per day. Each day takes a different section of the work: meeting the protector, tracing its formation, meeting what's underneath. Send the completed journal to me at chad@herstwellness.com by 48 hours before our session. This journal does the deepest work of the program on the page. You'll move from the protector you live with daily, through its formation, to the wound it's been guarding, and toward the move of meeting that wound with the kindness it never got. A note before you begin: this is the journal in the whole program that most warrants pacing. If at any point a section gets too big, stop. Take a walk. Come back to the breath. Sit with the Compassion meditation. Pick the journal up again the next day. The intensity isn't the point. The contact is. Don't compress the three sections into one sitting. Each section needs a night of sleep before the next.", "sections": [{"heading": "Before you begin each section", "note": "Take five minutes of breath first. The straw breath, five in, seven out. Let your body settle. When you've arrived, open your eyes and begin. If at any point the work gets overwhelming, back off. Switch to the breath. Place a hand on your chest. Open your eyes. Come back when the system has settled. Backing off isn't failure. It's the practice doing what it's supposed to do. # Day 1. Meeting the Protector", "prompts": []}, {"heading": "Name it", "prompts": [{"id": "protector-and-wound-1", "kind": "short", "label": "Name it", "text": "Of the protectors named in the chapter (the inner critic, the achiever, the caretaker, the suppressor of anger, the controller, the people-pleaser, the numbing one), which one is loudest in you? You don't need to choose a single one. Most people have a primary plus a backup or two. Name the one or two you most recognize."}]}, {"heading": "What it sounds like", "prompts": [{"id": "protector-and-wound-2", "kind": "long", "label": "What it sounds like", "text": "Write the protector's actual voice. The specific sentences it says to you, the tone, the cadence. Don't sanitize it. If your inner critic calls you a fucking idiot, write *fucking idiot*. If your achiever says *you have to do more or they'll see through you*, write that. The point isn't to vent. The point is to render the protector specifically enough that you can see it as a voice rather than as you."}]}, {"heading": "What it does to you", "prompts": [{"id": "protector-and-wound-3", "kind": "long", "label": "What it does to you", "text": "How does the protector show up in your daily life? What behaviors does it run? What does it stop you from doing? What does it push you to do that you wouldn't otherwise?"}]}, {"heading": "Where it lives in the body", "prompts": [{"id": "protector-and-wound-4", "kind": "long", "label": "Where it lives in the body", "text": "Bring the protector to mind now. Hear its voice in your head for a few breaths. Now drop into your body. Where do you feel the protector physically? The throat that clamps when it's active? The chest that tightens? The gut that grips? The shoulders that brace? The jaw that locks? Find the specific location. Describe what it feels like. Tight, hot, hollow, heavy, sharp, cold, jumpy, frozen."}]}, {"heading": "Its positive intent", "prompts": [{"id": "protector-and-wound-5", "kind": "long", "label": "Its positive intent", "text": "This is the move from the Protector chapter. Drop the question into the body, not the mind: *what are you trying to protect me from?* Wait. Don't answer with your head. Wait for what arises. The answer often comes as a sentence the protector would say, sometimes a memory, sometimes a sensation that shifts. Write whatever comes."}]}, {"heading": "Honor it", "prompts": [{"id": "protector-and-wound-6", "kind": "short", "label": "Honor it", "text": "Write a sentence or two of acknowledgment to the protector. Something like: *I see you. You've been working hard for a long time. Thank you.* Or your own version of that. Notice what happens in your body when you offer that. Often the bracing eases slightly. The protector doesn't disappear. It softens. Note what you notice. # Day 2. Tracing Its Formation Last night you slept on the protector. Today we look at where it came from."}]}, {"heading": "Before you begin", "note": "Five minutes of breath. Let your body settle.", "prompts": []}, {"heading": "When did the protector form", "prompts": [{"id": "protector-and-wound-7", "kind": "long", "label": "When did the protector form", "text": "Most protectors form in childhood, often early. Some can be traced to specific moments. Some are more diffuse: an accumulation of years of conditions. Bring your protector to mind. The one you named yesterday. Ask: *when did you start running?* You may get a specific memory. You may get an age. You may get a felt sense of a particular room or season. You may get a general impression. Whatever comes, write it."}]}, {"heading": "What was the room like", "prompts": [{"id": "protector-and-wound-8", "kind": "long", "label": "What was the room like", "text": "Describe the conditions the protector was forming inside. Who was in the room (the family, the school, the neighborhood). What was the emotional climate. What was the protector responding to. What was the room asking of you that required you to develop this particular adaptation. You don't need a tidy story. Fragments are fine. Atmospheres are fine. Bodily memories are fine."}]}, {"heading": "The trade you made", "prompts": [{"id": "protector-and-wound-9", "kind": "long", "label": "The trade you made", "text": "The protector formed because you traded something for it. To get the safety the protector provided, you gave something up. The trade was rarely conscious. It happened over time, in many small moments. What did you trade? Your spontaneity? Your sensitivity? Your anger? Your needs? Your particular kind of joy? Your honesty about what you actually wanted? Try to name it as specifically as you can. *I traded my willingness to cry for being seen as the strong one.* *I traded my anger for staying close to my mother.* *I traded my needing things for being the easy kid who didn't add weight.*"}]}, {"heading": "The inheritance", "prompts": [{"id": "protector-and-wound-10", "kind": "long", "label": "The inheritance", "text": "Look at the protector and the trade. Where in your family did this pattern exist before you? Did your mother run a version of this protector? Did your father? Your grandparents? Most of the wound was inherited. The contract didn't begin with you. Naming the lineage doesn't absolve anyone. It gives you accurate information about what you're carrying. What's the lineage of your particular protector? # Day 3. Meeting What's Underneath Two days in. The protector is named. The formation is mapped. The trade is visible. Today we turn toward what the protector has been guarding. This is the deepest section. Move slowly. Stop and back off if the work gets too big."}]}, {"heading": "Before you begin", "note": "Ten minutes of breath today. Take the extra time to settle. Sit with the Compassion meditation if you have time. The deeper you go today, the more the nervous system wants regulation first.", "prompts": []}, {"heading": "Drop into the body", "prompts": [{"id": "protector-and-wound-11", "kind": "long", "label": "Drop into the body", "text": "Bring the protector to mind one more time. Find its location in the body. Stay with the location for a few breaths. Now, gently, see if you can sense underneath the protector. Not by pushing through. By letting your attention soften past the protector's edge. What's underneath? Often it's a quieter, more tender sensation than the protector itself. A hollow place. A small ache. A heaviness. A frightened pulse. A sadness with no particular shape. Describe what you find. Where in the body. What quality. Don't analyze it. Just locate it and let it be there."}]}, {"heading": "What this is", "prompts": [{"id": "protector-and-wound-12", "kind": "long", "label": "What this is", "text": "The thing underneath the protector is the wound. It's not a memory. It's not a story. It's the somatic imprint of the trade you made and have been making for decades. Sit with the sensation for a few minutes. Don't try to change it. Don't try to fix it. Just keep it company, the way the Be With practice from Module 3 taught. After a few minutes, see if anything surfaces. A memory. A line. A younger you. A specific moment. An image. Sometimes nothing comes and the sensation just shifts. Whatever happens, write it."}]}, {"heading": "The younger one", "prompts": [{"id": "protector-and-wound-13", "kind": "long", "label": "The younger one", "text": "The wound is usually carried by a younger version of you. A specific age. A specific tenderness. A specific moment of having to leave yourself. If a younger you surfaced, describe them. How old were they? Where were they? What were they feeling? What did they need that they didn't get? If no specific younger you surfaced, that's fine. Sometimes the body offers a sensation without a clear image. Write what was there."}]}, {"heading": "The offering", "prompts": [{"id": "protector-and-wound-14", "kind": "long", "label": "The offering", "text": "Now write directly to the wound. Or to the younger you, if one is present. Say what you'd say to a child who'd been carrying this alone for forty years. It doesn't have to be eloquent. Often the simplest things land hardest. *I see you. I'm here. You don't have to do this alone anymore. I'm sorry no one was there for this when you needed them. I'm here now.* Notice what happens in your body as you write the words. Don't perform them. Don't compassion-impressively. Just let them land in you as you write."}]}, {"heading": "What changed", "prompts": [{"id": "protector-and-wound-15", "kind": "long", "label": "What changed", "text": "Look at your body now. Compare it to where you started today. What's different? Even small shifts count. Looser breath. A softening in the throat. Some warmth in the chest where there'd been ice. A quiet you didn't have an hour ago. What did you learn today that you want to remember?"}]}, {"heading": "What you want to bring to our session", "prompts": [{"id": "protector-and-wound-16", "kind": "short", "label": "What you want to bring to our session", "text": "One sentence. The thing from this three-day journal that most wants to be brought into the room when we meet."}]}]},
  {"module": 5, "slug": "session-prep-5", "code": "05.05", "kind": "Session prep", "title": "Session Prep", "blurb": "What's been most alive for you in the last two weeks? In your work, in your relationships, in your body.…", "intro": "Twenty-four hours before our session. Slow this one down. The territory has been tender. The last two weeks with the protector, the wound, and the practice of meeting it with compassion. What surfaced. What didn't. What's still raw. What you most want to bring to me. We'll begin from what's most alive.", "sections": [{"heading": "Before you begin", "note": "Take a few minutes of breath first. Sit with your eyes closed. Let your body settle. When you've arrived, open your eyes and begin writing.", "prompts": []}, {"heading": "1. What's been alive", "prompts": [{"id": "session-prep-5-1", "kind": "long", "label": "1. What's been alive", "text": "What's been most alive for you in the last two weeks? In your work, in your relationships, in your body. What's been pulling your attention? What's been hard? What's been opening? You don't have to write a comprehensive update. Just what's been close to the surface."}]}, {"heading": "2. The protector you've been working with", "prompts": [{"id": "session-prep-5-2", "kind": "long", "label": "2. The protector you've been working with", "text": "Which protector showed up most in the Protector and Wound Journal? What did you learn about it that you hadn't seen before? How does naming it as a protector (rather than as a flaw or as you) change your relationship to it? If a different protector has surfaced as more important since you started the journal, name that one instead."}]}, {"heading": "3. The wound underneath", "prompts": [{"id": "session-prep-5-3", "kind": "long", "label": "3. The wound underneath", "text": "What did you find when you turned toward what the protector has been guarding? Where in the body did it live? What surfaced when you stayed with it (a memory, a sentence, a younger you, a sensation that shifted)? If you didn't make it all the way to the wound, name what you sensed was there. The hint of it. The shape of what wasn't quite available yet."}]}, {"heading": "4. The Compassion practice", "prompts": [{"id": "session-prep-5-4", "kind": "long", "label": "4. The Compassion practice", "text": "How's the daily sit landing? Where is it opening, where is it sticking? Be specific where you can. *I sat with version one and couldn't feel anything for the first ten minutes* is more useful than *it went fine*. So is *the hand on the heart felt strange and then on day seven I cried unexpectedly*. If the practice has been hard to do at all, name that. Resistance at this point in the program is information."}]}, {"heading": "5. What you want to focus on in our session", "prompts": [{"id": "session-prep-5-5", "kind": "long", "label": "5. What you want to focus on in our session", "text": "What's the thing you most want to bring to our session? A specific protector you can't get under. A wound that surfaced and felt too big to meet alone. A pattern from childhood you've started to see clearly for the first time. A line your younger self said that's still ringing. If multiple things are on your mind, name them all. We can decide together where to start."}]}]},
  {"module": 5, "slug": "follow-up-5", "code": "05.05A", "kind": "Journal", "title": "Follow-Up", "blurb": "Address the wound directly. Use whatever name fits. *Hello Not-Enough.* *Dear Fear of Abandonment.* *To my…", "intro": "Complete within 24 to 48 hours of our session, while what came up is still close to the surface. Send to me at chad@herstwellness.com when you're done. This isn't a six-prompt journal. It's a letter. You've spent the last two weeks naming the protector, tracing its formation, and meeting what's underneath. In our session, we sat with the wound directly. Now you're going to write to it. A letter to the sacred wound does something the other journals don't. It addresses the wound as something rather than as nothing. As a presence you've been living with, not as a defect you have to keep cleaning up. The act of writing to it changes the relationship. The wound stops being the unspeakable thing under the protector and becomes a companion you can finally talk to. Write it long. Let it pour out. Don't polish. If emotion rises, let it.", "sections": [{"heading": "Before you begin", "note": "Five minutes of breath first. Five in, seven out. Let your body settle. Then open your eyes and write.", "prompts": []}, {"heading": "1. Name it", "prompts": [{"id": "follow-up-5-1", "kind": "short", "label": "1. Name it", "text": "Address the wound directly. Use whatever name fits. *Hello Not-Enough.* *Dear Fear of Abandonment.* *To my Vigilance.* *To the part of me that never feels safe being seen.* *Hello Perfectionism.* Naming is the beginning. Once you name it, you've located it. Once you've located it, you can talk to it. What's your wound's name? Write it as the salutation of your letter."}]}, {"heading": "2. Describe its presence", "prompts": [{"id": "follow-up-5-2", "kind": "long", "label": "2. Describe its presence", "text": "Tell the wound how it's shown up in your life. Be specific. Childhood moments, family dynamics, work, relationships, your body, your private hours. Use vivid memories. Sensory details. Actual examples. Don't generalize. The wound has been with you in specific rooms, on specific days, with specific people. Name them."}]}, {"heading": "3. Unpack the narratives it gave you", "prompts": [{"id": "follow-up-5-3", "kind": "long", "label": "3. Unpack the narratives it gave you", "text": "The wound came with a set of stories about who you are. What have you told yourself because of this wound? What messages did you absorb from the people around you, from your culture, from the assumptions in the rooms you grew up in? Write the stories out plainly. *I told myself I had to earn the right to take up space.* *I told myself my anger would drive people away.* *I told myself my body had to be perfected before I could be loved.* Your own version."}]}, {"heading": "4. Acknowledge the harm", "prompts": [{"id": "follow-up-5-4", "kind": "long", "label": "4. Acknowledge the harm", "text": "Speak honestly about what the wound has cost you. Don't sugarcoat it. Name the consequences in your mental life, your emotional life, your body, your relationships, your sense of yourself. What has the wound taken from you? What has it kept you from doing? Where has it sent you astray?"}]}, {"heading": "5. Recognize the gifts", "prompts": [{"id": "follow-up-5-5", "kind": "long", "label": "5. Recognize the gifts", "text": "This is the Chiron move. The Greek myth of the centaur who carried an unhealable wound and, in learning to live with it, became the great teacher of medicine. His power came from the wound. He couldn't heal himself. That was the source of his ability to heal others. The same paradox lives in you. The sensitivity that got punished became your capacity to attune to others. The vigilance that came from an unpredictable house became your skill at reading rooms. The anger that wasn't allowed became fuel for your leadership. The need to be the strong one for a fragile parent became the reliability others lean on now. Whatever your wound's particular shape is, it has a corresponding gift. Name the gifts. Specifically. What does this wound, when you stop running from it, give you? What capacities have come out of it? What can you offer others because of it that you couldn't offer without it? Don't romanticize. The wound hurt. The cost was real. And the gifts are real too. Both are true."}]}, {"heading": "6. Your evolving relationship", "prompts": [{"id": "follow-up-5-6", "kind": "long", "label": "6. Your evolving relationship", "text": "After these two weeks, how is your relationship with the wound changing? What parts of it do you want to keep as strengths? What parts are you ready to begin setting down?"}]}, {"heading": "7. Close with intention", "prompts": [{"id": "follow-up-5-7", "kind": "long", "label": "7. Close with intention", "text": "End the letter. A sentence or two. Something like *thank you for what you've taught me, and I'm ready to begin carrying this differently.* Or your own version. Speak to the wound as you'd speak to a long-time companion you're about to walk into a new chapter with."}]}, {"heading": "Optional: read it aloud", "note": "If you have someone trustworthy in your life, consider reading the letter to them. Not for feedback. Just to let it land in another person's presence. Some of the wound's grip comes from having been kept private for so long. Speaking it aloud, to a witness, releases some of that grip in a way that solo writing can't quite. If you don't have someone, that's fine. The letter has already done its work in the writing. You can read it aloud to yourself, or to me when we next meet.", "prompts": []}, {"heading": "Bridging to Module 6", "note": "The gifts you named in section five aren't abstract. They're the specific capacities that become available to you as Module 6 begins. Module 5 closes the inner half of the program. We've come home to the part of you that was buried. Module 6 begins the outer half. STEP. The work of bringing what you've come home to into your actual relationships, your actual conversations, your actual choices. The contract you've been honoring with the people in your life can finally be renegotiated, because the one who signed it, the original self underneath all the protection, is back online enough to have something to say. The gifts the wound carries become the thing the world finally gets from you. Not the performance. Not the protector. The thing the wound was guarding all along. That's what STEP is for. We start it in two weeks. Send the letter when you're done. I'll read it before our next session.", "prompts": []}, {"heading": "A note about this letter", "note": "Keep it. The other follow-up journals in this program are session-integration tools. Useful in the week after we meet, less so a month later. This one is different. It's an artifact. You may go back and read it in a year, in five years. The wound the letter is addressed to isn't going anywhere, and the version of you that exists a year from now is going to want to know what this version of you saw and named here. Don't lose the file.", "prompts": []}]},
  {"module": 6, "slug": "natural-strengths", "code": "06.03A", "kind": "Journal", "title": "Natural Strengths", "blurb": "Read through all fifteen. Notice which three feel most like you when you're not trying to be anything at all.…", "intro": "Complete this journal as you work through Module 6. Take it at your own pace, ideally alongside the friend interviews you're setting up in 06.03B. The deeper you go here, the more there is for us to work with in our session. These qualities are already in you. They show up when you're not performing. The work of this journal is to choose the three that feel most like home, then explore where each one shows up in your life and where it came from.", "sections": [{"heading": "The Fifteen Qualities", "prompts": [{"id": "natural-strengths-1", "kind": "short", "label": "Read through all fifteen", "text": "Read through all fifteen. Notice which three feel most like you when you're not trying to be anything at all. The ones that steady you, light you up, or feel most like home in your body."}, {"id": "natural-strengths-2", "kind": "short", "label": "Grounded", "text": "**Grounded.** I stay calm when things get messy. I hold steady when others can't."}, {"id": "natural-strengths-3", "kind": "short", "label": "Perceptive", "text": "**Perceptive.** I pick up on what isn't being said. I sense what's underneath."}]}, {"heading": "Quality #1: Deep Dive", "prompts": [{"id": "natural-strengths-4", "kind": "short", "label": "Write the quality name, then work through the prompts below", "text": "Write the quality name, then work through the prompts below."}, {"id": "natural-strengths-5", "kind": "short", "label": "1", "text": "**1. Describe a specific moment where this quality was alive in you. What action did you take?**"}, {"id": "natural-strengths-6", "kind": "short", "label": "2", "text": "**2. What felt completely natural about it?**"}, {"id": "natural-strengths-7", "kind": "short", "label": "3", "text": "**3. How do you sense it affected others or shifted the situation?**"}, {"id": "natural-strengths-8", "kind": "short", "label": "4", "text": "**4. What part of that experience made you feel deeply aligned?**"}, {"id": "natural-strengths-9", "kind": "short", "label": "5", "text": "**5. Where do you think this part of you came from? What did it first show up to protect?**"}]}, {"heading": "Quality #2: Deep Dive", "prompts": [{"id": "natural-strengths-10", "kind": "short", "label": "Write the quality name, then work through the prompts below", "text": "Write the quality name, then work through the prompts below."}, {"id": "natural-strengths-11", "kind": "short", "label": "1", "text": "**1. Describe a specific moment where this quality was alive in you. What action did you take?**"}, {"id": "natural-strengths-12", "kind": "short", "label": "2", "text": "**2. What felt completely natural about it?**"}, {"id": "natural-strengths-13", "kind": "short", "label": "3", "text": "**3. How do you sense it affected others or shifted the situation?**"}, {"id": "natural-strengths-14", "kind": "short", "label": "4", "text": "**4. What part of that experience made you feel deeply aligned?**"}, {"id": "natural-strengths-15", "kind": "short", "label": "5", "text": "**5. Where do you think this part of you came from? What did it first show up to protect?**"}]}, {"heading": "Quality #3: Deep Dive", "prompts": [{"id": "natural-strengths-16", "kind": "short", "label": "Write the quality name, then work through the prompts below", "text": "Write the quality name, then work through the prompts below."}, {"id": "natural-strengths-17", "kind": "short", "label": "1", "text": "**1. Describe a specific moment where this quality was alive in you. What action did you take?**"}, {"id": "natural-strengths-18", "kind": "short", "label": "2", "text": "**2. What felt completely natural about it?**"}, {"id": "natural-strengths-19", "kind": "short", "label": "3", "text": "**3. How do you sense it affected others or shifted the situation?**"}, {"id": "natural-strengths-20", "kind": "short", "label": "4", "text": "**4. What part of that experience made you feel deeply aligned?**"}, {"id": "natural-strengths-21", "kind": "short", "label": "5", "text": "**5. Where do you think this part of you came from? What did it first show up to protect?**"}]}, {"heading": "Looking Across the Three", "prompts": [{"id": "natural-strengths-22", "kind": "long", "label": "Step back and explore where these qualities have lived in yo", "text": "Step back and explore where these qualities have lived in your life."}, {"id": "natural-strengths-23", "kind": "long", "label": "1", "text": "**1. Think of a time you gave something that felt natural and needed, not to impress, just because it was you being you. What were you doing? What qualities were alive in you? What did your presence offer? How did you feel afterward?**"}, {"id": "natural-strengths-24", "kind": "long", "label": "2", "text": "**2. Where does that part of you come from? What has it protected? What has it carried? Was it shaped by a wound or a moment that asked you to grow up fast? What vow or instinct was born from that?**"}]}, {"heading": "The Thread That Holds", "prompts": [{"id": "natural-strengths-25", "kind": "long", "label": "The Thread That Holds", "text": "After reflecting on these qualities and stories, what quality in you keeps showing up no matter the job, season, or circumstance? The part that others rely on, that doesn't need to be forced, that just seems to come out naturally? And what would it look like to live with more trust in that part of you? *This is the beginning of your life purpose statement.*"}]}]},
  {"module": 6, "slug": "session-prep-6", "code": "06.05", "kind": "Session prep", "title": "Session Prep", "blurb": "What's been most alive for you in the last few weeks? In your work, in your relationships, in your body.…", "intro": "Twenty-four hours before. Send it ahead so I can sit with what you've brought. The last few weeks with the Heartfelt Intentions work, the friend interviews, and the daily GCC sit. The work has shifted from inward to outward. Bring what's been emerging.", "sections": [{"heading": "1. What's been alive", "prompts": [{"id": "session-prep-6-1", "kind": "long", "label": "1. What's been alive", "text": "What's been most alive for you in the last few weeks? In your work, in your relationships, in your body. What's been pulling your attention? What's been hard? What's been opening? You don't have to write a comprehensive update. Just what's been close to the surface."}]}, {"heading": "2. The five stories", "prompts": [{"id": "session-prep-6-2", "kind": "long", "label": "2. The five stories", "text": "Which of the five Heartfelt Intentions stories surfaced the most for you? Was there one that surprised you, or one that hit harder than expected? What value or longing started to show itself through the writing? If the stories are still in progress, name where you are with them and what's still loading."}]}, {"heading": "3. The friend interviews", "prompts": [{"id": "session-prep-6-3", "kind": "long", "label": "3. The friend interviews", "text": "How were the conversations? What did you hear that you weren't expecting? What did one of your three reflect back that landed as true? What did you flinch from? Send me your notes and the completed forms alongside this prep."}]}, {"heading": "4. A trade you caught", "prompts": [{"id": "session-prep-6-4", "kind": "long", "label": "4. A trade you caught", "text": "Has there been a moment over the last few weeks when you noticed a trade about to happen? Describe it briefly. What was the body signal? What did you almost give away? Did you make the trade or not? If nothing has surfaced yet, name what you've been noticing in your GCC sit instead, especially in the Choice movement."}]}, {"heading": "5. What you want to focus on in our session", "prompts": [{"id": "session-prep-6-5", "kind": "long", "label": "5. What you want to focus on in our session", "text": "What's the thing you most want to bring to our session? A specific story you want to work, a value you can't quite name, a friend reflection that surprised you, a bind you've been seeing in your life that you want to look at together. If multiple things are on your mind, name them all. We can decide together where to start."}]}]},
  {"module": 6, "slug": "follow-up-6", "code": "06.05A", "kind": "Journal", "title": "Follow-Up", "blurb": "Enter your five intentions here for reference. Each one gets approached from a different angle…", "intro": "Complete within 24 to 48 hours of our session. Send your responses to me at chad@herstwellness.com when you're done. You have your heartfelt intentions and your life purpose statements named. Now the work is to start catching where you're trading them away. This journal is tune in to the trade in slow motion, applied to your own language. Each intention and each purpose statement is approached from a different angle. The goal isn't to be thorough. It's to see clearly. By the end, you'll have a sharper picture of where the binds are running and which trades you're ready to stop making. Don't try to do all of this in one sitting. Start with the intention that feels most alive right now. Let the journal be a conversation, not a sprint.", "sections": [{"heading": "Part 1: Where You're Trading Your Heartfelt Intentions", "prompts": [{"id": "follow-up-6-1", "kind": "short", "label": "Enter your five intentions here for reference", "text": "Enter your five intentions here for reference. Each one gets approached from a different angle below."}, {"id": "follow-up-6-2", "kind": "short", "label": "### Intention #1: The daily trade", "text": "### Intention #1: The daily trade"}, {"id": "follow-up-6-3", "kind": "short", "label": "Reference your first intention", "text": "Reference your first intention."}, {"id": "follow-up-6-4", "kind": "short", "label": "Where are you trading this away in small, everyday ways? Whe", "text": "Where are you trading this away in small, everyday ways? Where does a part of you go quiet so a connection stays intact? Notice the ordinary moments, not the dramatic ones. The small swallowed sentence. The thing you didn't mention. The agreement made on the surface while your body was disagreeing underneath."}, {"id": "follow-up-6-5", "kind": "short", "label": "### Intention #2: The feeling you're burying", "text": "### Intention #2: The feeling you're burying"}, {"id": "follow-up-6-6", "kind": "short", "label": "Reference your second intention", "text": "Reference your second intention."}, {"id": "follow-up-6-7", "kind": "long", "label": "What feeling are you about to bury to keep the peace? Where ", "text": "What feeling are you about to bury to keep the peace? Where is this intention asking you to feel something you've been managing instead? Anger you've been swallowing. Grief you've been postponing. Tenderness you've been hiding. Name what wants to come up when you stop holding it down."}, {"id": "follow-up-6-8", "kind": "short", "label": "### Intention #3: Right now, what are you about to trade?", "text": "### Intention #3: Right now, what are you about to trade?"}, {"id": "follow-up-6-9", "kind": "long", "label": "Reference your third intention", "text": "Reference your third intention."}, {"id": "follow-up-6-10", "kind": "short", "label": "Look at the next 48 hours", "text": "Look at the next 48 hours. What specific thing are you about to give away? Pick from the list, or write your own. Then describe where it's about to happen and with whom."}, {"id": "follow-up-6-11", "kind": "long", "label": "- My honesty - My time - My need - My dignity - My rest", "text": "- My honesty - My time - My need - My dignity - My rest"}, {"id": "follow-up-6-12", "kind": "short", "label": "### Intention #4: The bind underneath", "text": "### Intention #4: The bind underneath"}, {"id": "follow-up-6-13", "kind": "long", "label": "Reference your fourth intention", "text": "Reference your fourth intention."}, {"id": "follow-up-6-14", "kind": "short", "label": "What's the double bind here? Where does it feel like every o", "text": "What's the double bind here? Where does it feel like every option violates something? Both choices feel like betrayal. Both costs feel unbearable. Describe the bind in your life right now where this intention is the thing being lost no matter which way you turn."}, {"id": "follow-up-6-15", "kind": "long", "label": "### Intention #5: The third option", "text": "### Intention #5: The third option"}]}, {"heading": "Part 2: Where You're Trading Your Life Purpose", "prompts": [{"id": "follow-up-6-16", "kind": "short", "label": "Enter your three life purpose statements here for reference", "text": "Enter your three life purpose statements here for reference. Each one gets a different angle on the trade."}, {"id": "follow-up-6-17", "kind": "short", "label": "Life Purpose Statement 1:", "text": "**Life Purpose Statement 1:**"}, {"id": "follow-up-6-18", "kind": "short", "label": "Life Purpose Statement 2:", "text": "**Life Purpose Statement 2:**"}, {"id": "follow-up-6-19", "kind": "short", "label": "Life Purpose Statement 3:", "text": "**Life Purpose Statement 3:**"}, {"id": "follow-up-6-20", "kind": "long", "label": "### Life Purpose Statement #1: Where the gift turns against ", "text": "### Life Purpose Statement #1: Where the gift turns against you"}, {"id": "follow-up-6-21", "kind": "short", "label": "Reference your first life purpose statement", "text": "Reference your first life purpose statement."}, {"id": "follow-up-6-22", "kind": "long", "label": "Every gift has a shadow", "text": "Every gift has a shadow. When does this purpose turn against you? When does the same instinct that's a contribution under awareness become an overextension under fear? Where are you giving past your limits, organizing your day around a need you didn't sign up for, exhausting yourself in the name of an offering nobody actually asked for?"}, {"id": "follow-up-6-23", "kind": "short", "label": "### Life Purpose Statement #2: Where you're holding it back", "text": "### Life Purpose Statement #2: Where you're holding it back"}, {"id": "follow-up-6-24", "kind": "long", "label": "Reference your second life purpose statement", "text": "Reference your second life purpose statement."}]}, {"heading": "Part 3: Setting up Module 7", "prompts": [{"id": "follow-up-6-25", "kind": "long", "label": "The next module is about what you do once you've tuned in", "text": "The next module is about what you do once you've tuned in. Two pieces of work come up there: finding the third option (**E. Expand Options**) and saying the true thing out loud (**P. Practice**). Use the prompts below to start."}, {"id": "follow-up-6-26", "kind": "long", "label": "1", "text": "**1. Where's the binary in your life right now? Where are you stuck between two options that both feel like betrayal? Describe the binary you're inside.**"}, {"id": "follow-up-6-27", "kind": "long", "label": "2", "text": "**2. If you let yourself imagine a third option, the move the bind told you wasn't available, what comes to mind? It probably won't be perfect. It probably won't be dramatic. Trust the small one that shows up first.**"}]}, {"heading": "Part 4: The Anchor", "prompts": [{"id": "follow-up-6-28", "kind": "long", "label": "Part 4: The Anchor", "text": "Write one sentence to yourself, from yourself, as a reminder of who you are when you're not trading. This is what you'll come back to. *This is the work. Not the understanding. The living. Module 7 is where you start making the third option real.*"}]}]},
  {"module": 7, "slug": "stop-look-go", "code": "07.02A", "kind": "Journal", "title": "Stop-Look-Go", "blurb": "What are the two options that both feel like betrayal? Describe both, as your nervous system experiences…", "intro": "Complete this journal once early in Module 7. Pick one binary in your life you've been caught inside. Use this journal to find your version of the third option. Plan on 45 to 60 minutes. You don't have to pick the biggest binary in your life right now. A medium-sized one is better. Something that's been running quietly for a while, where you've been swallowing one of the options as the cost of admission. The work here is to slow that pattern down and see the third option that's been waiting.", "sections": [{"heading": "1. Name the binary", "prompts": [{"id": "stop-look-go-1", "kind": "long", "label": "1. Name the binary", "text": "What are the two options that both feel like betrayal? Describe both, as your nervous system experiences them. Don't soften them yet. *Either I say the truth and ___, or I stay silent and ___.* Or whatever the shape of yours is."}]}, {"heading": "2. Stop. Settle the body.", "prompts": [{"id": "stop-look-go-2", "kind": "long", "label": "2. Stop. Settle the body.", "text": "Take a few minutes of breath. Eyes closed if it helps. Bring the binary back into awareness and notice what your body is doing. Where do you feel it? Chest, throat, gut, shoulders, jaw? What's the texture? Tight, hollow, hot, buzzy? Don't try to fix any of it. Just let your body know you've noticed it's activated. Write what you found."}]}, {"heading": "3. Look. What got hit?", "prompts": [{"id": "stop-look-go-3", "kind": "long", "label": "3. Look. What got hit?", "text": "Which of your heartfelt intentions or your life purpose statements is being violated or dishonored in this binary? Not *what happened* on the surface. What got bumped into in you that mattered? What value is being asked to disappear for the relationship, the role, the outcome to stay intact?"}]}, {"heading": "4. Look. What's the bind setting it up?", "prompts": [{"id": "stop-look-go-4", "kind": "long", "label": "4. Look. What's the bind setting it up?", "text": "What's the structural setup that makes both options feel like betrayal? Whose signal told you to disappear when this kind of situation arises? Whose voice is the protector using right now? Where did this bind get installed? You don't have to solve the origin. Just see it."}]}, {"heading": "5. Find the third option", "prompts": [{"id": "stop-look-go-5", "kind": "long", "label": "5. Find the third option", "text": "What's the move you haven't considered? The third option is usually smaller than you expect. Less dramatic than you fear. It's the move the bind told you wasn't available. If it doesn't arrive immediately, try this: hold each of the two binary options in turn and notice what your body does with each. Then ask, *what's the move that doesn't require either of those costs?* The body usually senses it before the mind names it. Describe what comes up. It can be tentative. It doesn't have to be the perfect answer."}]}, {"heading": "6. Go. Take one small step.", "prompts": [{"id": "stop-look-go-6", "kind": "long", "label": "6. Go. Take one small step.", "text": "Name one specific, doable thing you could do in the next week that would act on the third option. Not the whole transformation. One move. The smaller the better. The sentence to say. The conversation to schedule. The pause to take. The one small refusal of the old contract. When could you do it? What's the smallest version that's still real?"}]}, {"heading": "To bring to our session", "prompts": [{"id": "stop-look-go-7", "kind": "long", "label": "To bring to our session", "text": "Anything in this work you want to bring to our next session? A specific moment you got stuck. A part of you that resisted the third option. A question about what comes next. The place where the binary still feels true even though you can see it."}]}]},
  {"module": 7, "slug": "expand-options", "code": "07.03A", "kind": "Journal", "title": "Expand Options", "blurb": "Describe the situation briefly. Who, what, when. Not the whole history. The specific moment or pattern you're…", "intro": "Complete this journal on one stuck situation in your life. Plan on 30 to 45 minutes. Have 07.03B Glossary of Mindsets open as a reference while you work through prompts 4 and 5. This journal walks you through the moves of Expand Options on one specific situation. Separating story from fact. Trying alternate stories. Looking through different mindsets. Letting the body tell you which frame opens something. Pick a situation where you've been stuck. A conflict that isn't moving. A decision you keep postponing. A pattern with a particular person that keeps repeating. Not the abstract version. One specific moment, one specific person, one specific choice.", "sections": [{"heading": "1. The situation", "prompts": [{"id": "expand-options-1", "kind": "long", "label": "1. The situation", "text": "Describe the situation briefly. Who, what, when. Not the whole history. The specific moment or pattern you're working with right now."}]}, {"heading": "2. Fact vs. story", "prompts": [{"id": "expand-options-2", "kind": "long", "label": "Two columns", "text": "Two columns. On the left, only the verifiable facts: what was said, what was done, what was observable. Pretend you're a court reporter. On the right, the story you've been telling about those facts: motive, meaning, predictions about what comes next."}, {"id": "expand-options-3", "kind": "long", "label": "If you find yourself writing conclusions in the fact column,", "text": "If you find yourself writing conclusions in the fact column, move them over. *She didn't care* is a conclusion. *She didn't respond when I said I was upset* is a fact."}]}, {"heading": "3. Three alternate stories", "prompts": [{"id": "expand-options-4", "kind": "short", "label": "Now try three other stories that fit the same facts", "text": "Now try three other stories that fit the same facts. They don't have to be flattering to you or to the other person. They just have to be plausible alternatives the facts could support."}, {"id": "expand-options-5", "kind": "short", "label": "After writing them, notice which one your body responds to m", "text": "After writing them, notice which one your body responds to most strongly. Which one softens something? Which one tightens something? Which one would you actually like to be true?"}]}, {"heading": "4. Two mindsets", "prompts": [{"id": "expand-options-6", "kind": "short", "label": "From the Glossary of Mindsets, pick two that feel different ", "text": "From the Glossary of Mindsets, pick two that feel different from each other. Try the situation through each one."}, {"id": "expand-options-7", "kind": "long", "label": "How does the situation look through this lens? What question", "text": "How does the situation look through this lens? What question does it ask? What does it bring into focus that was hidden?"}, {"id": "expand-options-8", "kind": "short", "label": "How does the situation look through this lens? What does it ", "text": "How does the situation look through this lens? What does it bring into focus?"}]}, {"heading": "5. Your inner board", "prompts": [{"id": "expand-options-9", "kind": "long", "label": "5. Your inner board", "text": "Look at the situation through your own heartfelt intentions and life purpose statements. Which one of your intentions is most violated here? Which one of your purpose statements would tell you to move differently? What does the situation look like when you hold it next to the values you've named?"}]}, {"heading": "6. The body's signal", "prompts": [{"id": "expand-options-10", "kind": "long", "label": "6. The body's signal", "text": "Sit for a few minutes. Drop attention into the body. Hold the situation in your awareness without trying to think about it. Notice where you feel it. What sensation arrives, what shifts. Then try the inverse. If the situation has a clear direction you've been considering, hold *I'm doing the thing* and notice the body's response. Then hold *I'm not doing the thing* and notice the body's response. What did you find?"}]}, {"heading": "7. The next true move", "prompts": [{"id": "expand-options-11", "kind": "long", "label": "7. The next true move", "text": "Based on the work above, what's the next true move? Not the heroic version. The small, specific, doable thing that opens something. The honest sentence. The question to ask. The pause to take. The small refusal of the story you'd been believing."}]}]},
  {"module": 7, "slug": "practice", "code": "07.04A", "kind": "Journal", "title": "Practice", "blurb": "What's the sentence you've been carrying? Write it as plainly as you can. No softening. No qualifying. The…", "intro": "Complete this journal once after reading the Practice chapter. Plan on 30 to 45 minutes. The journal walks you through identifying one honest sentence you've been postponing, naming the body texture around it, and finding the small practice move you could take this week. This is the work of P. Practice on the page. Pick one honest sentence you've been carrying without saying. One conversation you've been putting off. One boundary you've been hinting at but not naming. One ask you've been hoping the other person would just figure out.", "sections": [{"heading": "1. The honest sentence", "prompts": [{"id": "practice-1", "kind": "long", "label": "1. The honest sentence", "text": "What's the sentence you've been carrying? Write it as plainly as you can. No softening. No qualifying. The truth as it actually lives in you, before you dress it up."}]}, {"heading": "2. Who needs to hear it", "prompts": [{"id": "practice-2", "kind": "long", "label": "2. Who needs to hear it", "text": "Who is the person on the other end of the sentence? Be specific. One person. One relationship. (If multiple people need to hear it, pick the one where this sentence is loudest right now.) What is your role in their life, and theirs in yours? What's the relationship's shape?"}]}, {"heading": "3. The body's response", "prompts": [{"id": "practice-3", "kind": "long", "label": "3. The body's response", "text": "Close your eyes for a moment. Imagine saying the sentence to the person. Out loud. Their face in front of you. Your voice carrying it. What happens in your body? Where do you feel it? Tightness, heat, hollowness, a shift in breath? Don't try to argue your body out of the response. Just notice and name it."}]}, {"heading": "4. What the protector says", "prompts": [{"id": "practice-4", "kind": "long", "label": "4. What the protector says", "text": "The protector probably has a strong opinion about why you can't say this sentence. What does it say? Common protector arguments: *they'll get hurt. They won't understand. It'll make things worse. I'll regret it. I should wait until I'm calmer. I should figure out a better way to say it. They'll think I'm overreacting.* Write down what your protector is saying. All of it. Don't argue with it yet. Just get it on the page."}]}, {"heading": "5. What you're trading by not saying it", "prompts": [{"id": "practice-5", "kind": "long", "label": "5. What you're trading by not saying it", "text": "You've been carrying this sentence by not saying it. What is the not-saying costing you? In your body. In the relationship. In your sense of yourself. In the energy you have for the rest of your life. Be specific. The cost is usually higher than we let ourselves see."}]}, {"heading": "6. The small practice move", "prompts": [{"id": "practice-6", "kind": "long", "label": "6. The small practice move", "text": "What's the small, doable version of saying it this week? Not the perfect speech. Not the dramatic confrontation. The version that's true and that you could actually do. The medium matters. In person, on the phone, on video, by email, by text. The setup matters. With time to talk, in a stolen ten minutes, after dinner, before a meeting. Choose what's actually possible. Name the move. When could you do it? What's the smallest version that's still real?"}]}, {"heading": "7. Designing the alliance", "prompts": [{"id": "practice-7", "kind": "long", "label": "7. Designing the alliance", "text": "If the sentence lands well, the next move is to ask for what you'd want going forward. What's the small agreement you'd want to make about how this gets handled in the future? This isn't a demand. It's an ask. The other person can agree, modify, or push back. The point is to make the new arrangement visible instead of hoping the relationship reorganizes on its own. What would you ask for?"}]}, {"heading": "8. What you'll do regardless of how they respond", "prompts": [{"id": "practice-8", "kind": "long", "label": "8. What you'll do regardless of how they respond", "text": "A truth told well doesn't guarantee a good response. Sometimes the other person hears it. Sometimes they don't. Sometimes they need time. Sometimes they need a second conversation. What will you commit to doing for yourself, regardless of how the other person responds? Some examples: *I'll stay with my own body through the conversation. I won't rush to reassure them. I won't take back what I said the next morning. I'll let the discomfort be present without trying to fix it.* What's your version?"}]}]},
  {"module": 7, "slug": "session-prep-7", "code": "07.05", "kind": "Session prep", "title": "Session Prep", "blurb": "What's been most alive for you in the last two weeks? In your work, in your relationships, in your body.…", "intro": "Twenty-four hours. You know what this is. Two weeks with the third option work, the daily Conscious Choice sit, and the practice moves you've been taking. We're fifteen weeks in. Bring what's been hardest, what's been most alive, what you most want to work with in our time together.", "sections": [{"heading": "1. What's been alive", "prompts": [{"id": "session-prep-7-1", "kind": "long", "label": "1. What's been alive", "text": "What's been most alive for you in the last two weeks? In your work, in your relationships, in your body. What's been pulling your attention? What's been hard? What's been opening? You don't have to write a comprehensive update. Just what's been close to the surface."}]}, {"heading": "2. The binary you've been working", "prompts": [{"id": "session-prep-7-2", "kind": "long", "label": "2. The binary you've been working", "text": "Which binary has been running most loudly in your life? Describe it as your nervous system experiences it. What are the two options that both feel like betrayal? If multiple binaries are present, pick the one most worth working in our session."}]}, {"heading": "3. The third option", "prompts": [{"id": "session-prep-7-3", "kind": "long", "label": "3. The third option", "text": "Have you found a version of the third option in this binary? If so, what does it look like? Where in your body did it arrive, and what was the moment you noticed it? If you haven't found it yet, what's been getting in the way of seeing it? What's the protector telling you about why it isn't available?"}]}, {"heading": "4. A practice move you've tried", "prompts": [{"id": "session-prep-7-4", "kind": "long", "label": "4. A practice move you've tried", "text": "Have you taken a small practice move in the last two weeks? The utterance you said when you usually would have agreed. The little no. The U-turn back into the body before solving. The boundary you named. The conversation you almost backed out of. Describe what you did and what happened. Or describe the move you wanted to make but didn't. Both are useful information."}]}, {"heading": "5. What you want to focus on in our session", "prompts": [{"id": "session-prep-7-5", "kind": "long", "label": "5. What you want to focus on in our session", "text": "What's the thing you most want to bring to our session? A specific binary you can't see past. A practice move you're rehearsing. A relationship that needs a conversation. A pattern that keeps showing up no matter how clearly you see it. If multiple things are on your mind, name them all. We can decide together where to start."}]}]},
  {"module": 7, "slug": "follow-up-7", "code": "07.05A", "kind": "Journal", "title": "Follow-Up", "blurb": "What from our session is still moving in you? A moment, a sentence, an image, a question. Don't try to…", "intro": "Complete within 24 to 48 hours of our session. Send your responses to me at chad@herstwellness.com when you're done. This journal is the place where the work of our session lands in the body. The session named something. This is where you start to walk it forward. The prompts are spacious. Take them slowly. One sitting per prompt if you need that.", "sections": [{"heading": "1. What stayed with you", "prompts": [{"id": "follow-up-7-1", "kind": "long", "label": "1. What stayed with you", "text": "What from our session is still moving in you? A moment, a sentence, an image, a question. Don't try to organize it. Just write what's still alive."}]}, {"heading": "2. The bind, seen clearly", "prompts": [{"id": "follow-up-7-2", "kind": "long", "label": "2. The bind, seen clearly", "text": "After our session, can you name the bind you've been caught inside more cleanly than you could before? Write the binary in one sentence: *Either I ___ or I ___.* Then describe what makes both options feel like betrayal."}]}, {"heading": "3. The third option as you can sense it now", "prompts": [{"id": "follow-up-7-3", "kind": "long", "label": "3. The third option as you can sense it now", "text": "What does the third option look like for you in this bind? It may not be perfectly clear. It may be more of a direction than a destination. Describe what you can sense, and what's still uncertain."}]}, {"heading": "4. The small step you're taking", "prompts": [{"id": "follow-up-7-4", "kind": "long", "label": "4. The small step you're taking", "text": "What's the one specific, small move you're going to take in the next week to act on the third option? Not the full reinvention. One sentence to say. One conversation to schedule. One boundary to name. One pause to take. When will you do it? With whom? What's the smallest version that's still real?"}]}, {"heading": "5. What's already shifting", "prompts": [{"id": "follow-up-7-5", "kind": "long", "label": "5. What's already shifting", "text": "Even without acting yet, something has likely already shifted from doing this work. A small loosening in your chest. A different quality to your sleep. A moment when you caught a pattern in motion that you would have missed before. Name what you've noticed."}]}, {"heading": "6. What's still unfinished", "prompts": [{"id": "follow-up-7-6", "kind": "long", "label": "6. What's still unfinished", "text": "What's still tender, unresolved, or unclear? What is going to take more time, more sittings, more rounds before it lands fully? Naming it doesn't fix it. It just keeps it in the field instead of letting it disappear back into the protector's care."}]}]},
  {"module": 8, "slug": "heros-journey", "code": "08.02A", "kind": "Journal", "title": "Hero’s Journey", "blurb": "Describe your life before you were aware that something needed to change. Not the version you'd put in a…", "intro": "This journal is the most important assignment of Module 8. Take your time with it. Plan to spread it across two or three sittings rather than trying to do it in one. You'll work through the stages of the heroine's or hero's journey as you experienced them in your own life. Not in the abstract. The actual specifics. The story you've been living without quite naming it that way. Write longhand if you can. The slowness helps. If you type, type slowly. There are ten prompts. Don't skip any. The ones that feel hardest are usually the ones doing the most work.", "sections": [{"heading": "1. The Ordinary World", "prompts": [{"id": "heros-journey-1", "kind": "long", "label": "1. The Ordinary World", "text": "Describe your life before you were aware that something needed to change. Not the version you'd put in a Christmas letter. The real version. What was a typical week like? What was working on the surface? What was quietly off underneath? What were the coping mechanisms or distractions you were using to get through?"}]}, {"heading": "2. The Boiling Point", "prompts": [{"id": "heros-journey-2", "kind": "long", "label": "2. The Boiling Point", "text": "There's usually a moment, or a slow accumulation, when you can no longer pretend things are fine. Describe it. What happened, internally or externally, that made you realize something had to change? What couldn't you ignore anymore?"}]}, {"heading": "3. The Refusal", "prompts": [{"id": "heros-journey-3", "kind": "long", "label": "3. The Refusal", "text": "What part of you didn't want to do this work? What were the arguments your inner Mara made? *You don't have time. You can't afford it. It probably won't help. Other people don't need this kind of thing. You should be able to figure this out on your own.* Write the actual sentences as you remember hearing them."}]}, {"heading": "4. Crossing the Threshold", "prompts": [{"id": "heros-journey-4", "kind": "long", "label": "4. Crossing the Threshold", "text": "What did you finally commit to, and what did the commitment cost? What did you give up, change, or risk to begin? How did your daily life, your relationships, or the way you were spending your attention shift in those early weeks?"}]}, {"heading": "5. The Tests", "prompts": [{"id": "heros-journey-5", "kind": "long", "label": "Looking back at the early modules, what tested you? Where di", "text": "Looking back at the early modules, what tested you? Where did you almost quit? What were you sure wouldn't work, that you tried anyway? What were the small disciplines (showing up to calls, doing the journals, sitting when you didn't want to) that felt disproportionately hard at the time?"}, {"id": "heros-journey-6", "kind": "long", "label": "Now zoom out: how did those early tests prepare you for the ", "text": "Now zoom out: how did those early tests prepare you for the harder work that came later? What did they build in you, even when they felt like setbacks?"}]}, {"heading": "6. The Innermost Cave", "prompts": [{"id": "heros-journey-7", "kind": "long", "label": "6. The Innermost Cave", "text": "Every real journey has its night under the fig tree. Describe yours. What was the deepest interior work you did during this program? What did you find yourself sitting with that you'd spent a long time avoiding? What did you confront and, in some real way, come through? You don't have to make it sound dramatic. Just true."}]}, {"heading": "7. The Reward", "prompts": [{"id": "heros-journey-8", "kind": "long", "label": "7. The Reward", "text": "What have you actually gained? Be specific. Choose at least three from the list below, or substitute your own: - A new relationship with your sacred wound - A clearer sense of who you are when the kids on the bus aren't running the show - The ability to feel a sensation without immediately reacting to it - Heartfelt intentions or life purpose statements you can name and feel - A way of meeting your own difficult emotions that you didn't have before - Choices you've already made differently because of this work What are the rewards of the journey for you? Write about them with the specificity they deserve."}]}, {"heading": "8. The Refusal of the Return", "prompts": [{"id": "heros-journey-9", "kind": "long", "label": "8. The Refusal of the Return", "text": "There's a part of you, right now, that would prefer to keep this work to yourself. To not risk being misunderstood. To enjoy what you've found in private and let everyone else figure out their own way. Name it. What about coming back into your ordinary life, with these new capacities, feels risky or exposing? What's the quieter, more comfortable option you've been considering?"}]}, {"heading": "9. The Return", "prompts": [{"id": "heros-journey-10", "kind": "long", "label": "9. The Return", "text": "If you do come back, fully, with what you've learned: what changes? What does the next chapter look like? Who are you in your work, your relationships, your community, that you weren't before? This isn't a five-year plan. It's a rough sketch of who's coming home."}]}, {"heading": "10. The Through-Line", "prompts": [{"id": "heros-journey-11", "kind": "long", "label": "10. The Through-Line", "text": "Read back through everything you've just written. What's the through-line? What is this journey actually about, for you? In a few sentences, name what you've come to understand about your own life that you didn't understand at the start. This last answer doesn't have to be tidy. It just has to be yours. *Submit this journal to me at least 48 hours before our final session. I'll read it carefully and we'll work with it together.*"}]}]},
  {"module": 8, "slug": "your-road-back", "code": "08.02B", "kind": "Journal", "title": "Your Road Back", "blurb": "For each area, give yourself a quick rating from 1 (deeply dissatisfied) to 10 (deeply aligned with how you…", "intro": "Where the previous journal looked at where you've been, this one looks at where you're going. I want you to do something different from what most vision exercises ask. Most of those exercises ask you to imagine an ideal life across every possible domain. The result tends to be either generic or overwhelming, and it rarely produces real movement. Instead, you're going to do something focused. You'll briefly check in across the domains of your life, identify the two or three that matter most right now, and only do the deeper visioning work in those areas. This is on purpose. The integration phase asks you to make actual change, not articulate aspirational change. Two or three commitments you can actually live into will move your life more than seven you can't.", "sections": [{"heading": "Part 1: The check-in", "prompts": [{"id": "your-road-back-1", "kind": "short", "label": "For each area, give yourself a quick rating from 1 (deeply d", "text": "For each area, give yourself a quick rating from 1 (deeply dissatisfied) to 10 (deeply aligned with how you want it to be). Just a number, plus one sentence on why. Don't overthink. First instinct is usually right."}, {"id": "your-road-back-2", "kind": "short", "label": "Health and wellness", "text": "**Health and wellness.** Energy, sleep, eating, exercise, embodiment. Rating: \\_\\_\\_ / 10"}, {"id": "your-road-back-3", "kind": "short", "label": "Home life", "text": "**Home life.** Where you live, who you live with, how the daily rhythm of your home feels. Rating: \\_\\_\\_ / 10"}, {"id": "your-road-back-4", "kind": "short", "label": "Love and intimacy", "text": "**Love and intimacy.** Romantic partnership if you have one, or your relationship to romantic life if you don't. Rating: \\_\\_\\_ / 10"}, {"id": "your-road-back-5", "kind": "short", "label": "Family", "text": "**Family.** Parents, siblings, children, extended family. Whatever family means in your life. Rating: \\_\\_\\_ / 10"}, {"id": "your-road-back-6", "kind": "short", "label": "Work and career", "text": "**Work and career.** Whether what you do for work reflects who you are and what you're here to give. Rating: \\_\\_\\_ / 10"}, {"id": "your-road-back-7", "kind": "short", "label": "Personal growth", "text": "**Personal growth.** Your relationship to learning, practice, and your own continued development. Rating: \\_\\_\\_ / 10"}]}, {"heading": "Part 2: Choose two or three", "prompts": [{"id": "your-road-back-8", "kind": "short", "label": "Look back at your ratings", "text": "Look back at your ratings. The instinct is to pick the lowest scores, the areas where you're most dissatisfied. Resist that instinct. Sometimes those are right, but often the area that's a 4 is a 4 because it's not actually the most important to you, and you've made peace with it."}, {"id": "your-road-back-9", "kind": "short", "label": "What you're looking for is the area where the gap between wh", "text": "What you're looking for is the area where the gap between where it is and where it needs to be matters most to you right now. That might be a 3 that needs to be a 7. It might be a 6 that needs to be a 9. It might be a 7 that's been a 7 for years and you can feel it asking to grow."}, {"id": "your-road-back-10", "kind": "short", "label": "Pick two, or at most three, areas", "text": "Pick two, or at most three, areas. Write them here, with one sentence about why these are the ones."}]}, {"heading": "Part 3: For each chosen area, three questions", "prompts": [{"id": "your-road-back-11", "kind": "long", "label": "What's blocking it? What heartfelt intention or life purpose", "text": "**What's blocking it?** What heartfelt intention or life purpose statement of yours is being dishonored, or only partly honored, in this area? What's underneath the gap?"}, {"id": "your-road-back-12", "kind": "long", "label": "What's the picture? Paint a picture of what this area looks ", "text": "**What's the picture?** Paint a picture of what this area looks like three years from now if you live into your heartfelt intentions and life purpose around it."}, {"id": "your-road-back-13", "kind": "long", "label": "Three rules: (1) You can see it in your mind's eye", "text": "*Three rules: (1) You can see it in your mind's eye. (2) It's described in the positive (what is true, not what is no longer true). (3) It's measurable in some way.*"}, {"id": "your-road-back-14", "kind": "long", "label": "What's the first thirty days? What's one concrete thing you ", "text": "**What's the first thirty days?** What's one concrete thing you commit to doing in this area in the first thirty days after this program ends? Make it small enough to actually do."}, {"id": "your-road-back-15", "kind": "long", "label": "What's blocking it?", "text": "**What's blocking it?**"}, {"id": "your-road-back-16", "kind": "long", "label": "What's the picture?", "text": "**What's the picture?**"}, {"id": "your-road-back-17", "kind": "long", "label": "What's the first thirty days?", "text": "**What's the first thirty days?**"}, {"id": "your-road-back-18", "kind": "long", "label": "### Area 3 (optional)", "text": "### Area 3 (optional)"}, {"id": "your-road-back-19", "kind": "long", "label": "What's blocking it?", "text": "**What's blocking it?**"}]}, {"heading": "Part 4: Looking forward, in three quick questions", "prompts": [{"id": "your-road-back-20", "kind": "long", "label": "You've named two or three areas of your life that matter mos", "text": "You've named two or three areas of your life that matter most. To close, three short prompts about the work you've already done and the work waiting for you. Ten or fifteen minutes."}, {"id": "your-road-back-21", "kind": "long", "label": "### Where you've already been the change", "text": "### Where you've already been the change"}, {"id": "your-road-back-22", "kind": "long", "label": "Pick one specific situation from the past few months, in you", "text": "Pick one specific situation from the past few months, in your work, your family, or your community, where you showed up differently than you used to because of this work. Describe it briefly. What happened. What you would have done before. What you did instead. What changed in the room because of it."}]}, {"heading": "Closing", "note": "Look back at what you've written. The ratings, the chosen areas, the pictures, the thirty-day commitments, the small first step. This is what you're walking out of Mind/Body Foundations with. Not aspirations. Working material. *Submit this to me at least 48 hours before our final session. We'll work with it together.*", "prompts": []}]},
  {"module": 8, "slug": "new-invitation-part-1", "code": "08.04A", "kind": "Journal", "title": "New Invitation Part 1", "blurb": "**Why this person?** What about them makes you trust they can hold what you're going to share? What gives you…", "intro": "This journal is preparation for the three conversations you'll be having with the allies you're inviting into this next phase of your life. You don't need to script the conversations. But you do need to be clear, before you walk in, about who you're choosing and why, what you appreciate about them, and what specific kind of support you're asking for. Vagueness will not serve you in these conversations. Specificity will. Complete this journal before you have the conversations. Then complete Part 2 after.", "sections": [{"heading": "Who and why", "note": "You're going to identify three people. Choose carefully. Different people for different reasons. They don't all need to be your closest relationships. They need to be the ones who can recognize what you've done and help hold you to it.", "prompts": []}, {"heading": "Ally 1", "prompts": [{"id": "new-invitation-part-1-1", "kind": "short", "label": "Why this person? What about them makes you trust they can ho", "text": "**Why this person?** What about them makes you trust they can hold what you're going to share? What gives you confidence that they can recognize the new you and help you stay aligned with it?"}, {"id": "new-invitation-part-1-2", "kind": "long", "label": "What are their gifts? Be specific", "text": "**What are their gifts?** Be specific. What are this person's superpowers? What do they bring into a room? Some categories: deep listener, problem-solver, encourager, truth-teller, the one who helps you see your blind spots, the one who makes you laugh when you most need it. Name your version in your own words."}, {"id": "new-invitation-part-1-3", "kind": "long", "label": "What do you appreciate about their presence in your life? Wh", "text": "**What do you appreciate about their presence in your life?** Why are you glad they exist? What does it mean to you that they're someone you can ask?"}, {"id": "new-invitation-part-1-4", "kind": "long", "label": "What kind of support are you asking for, specifically? Get s", "text": "**What kind of support are you asking for, specifically?** Get specific. (See examples at the end if you need them.)"}, {"id": "new-invitation-part-1-5", "kind": "long", "label": "Logistics", "text": "**Logistics.** Are you asking for regular check-ins? On what cadence? In person, on the phone, by text? Any other ground rules that would help you both?"}]}, {"heading": "Ally 2", "prompts": [{"id": "new-invitation-part-1-6", "kind": "short", "label": "Why this person? What about them makes you trust they can ho", "text": "**Why this person?** What about them makes you trust they can hold what you're going to share? What gives you confidence that they can recognize the new you and help you stay aligned with it?"}, {"id": "new-invitation-part-1-7", "kind": "long", "label": "What are their gifts? Be specific", "text": "**What are their gifts?** Be specific. What are this person's superpowers? What do they bring into a room?"}, {"id": "new-invitation-part-1-8", "kind": "long", "label": "What do you appreciate about their presence in your life? Wh", "text": "**What do you appreciate about their presence in your life?** Why are you glad they exist? What does it mean to you that they're someone you can ask?"}, {"id": "new-invitation-part-1-9", "kind": "long", "label": "What kind of support are you asking for, specifically?", "text": "**What kind of support are you asking for, specifically?**"}, {"id": "new-invitation-part-1-10", "kind": "long", "label": "Logistics", "text": "**Logistics.** Cadence? Medium? Ground rules?"}]}, {"heading": "Ally 3", "prompts": [{"id": "new-invitation-part-1-11", "kind": "short", "label": "What are their gifts?", "text": "**What are their gifts?**"}, {"id": "new-invitation-part-1-12", "kind": "long", "label": "What do you appreciate about their presence in your life?", "text": "**What do you appreciate about their presence in your life?**"}, {"id": "new-invitation-part-1-13", "kind": "long", "label": "What kind of support are you asking for, specifically?", "text": "**What kind of support are you asking for, specifically?**"}, {"id": "new-invitation-part-1-14", "kind": "long", "label": "Logistics", "text": "**Logistics.** Cadence? Medium? Ground rules?"}]}, {"heading": "Examples of specific support", "note": "- *I want you to be someone I can text when I'm spiraling, and have you remind me what I'm actually committed to.* - *I want us to have a fifteen-minute call once a month where I tell you how the practice is going, and you ask hard questions if you sense I'm drifting.* - *I want permission to be honest with you about hard stuff, knowing you won't try to fix it, just witness it.* - *I want you to call me out, gently but clearly, when you see me reverting to the old version of myself.*", "prompts": []}, {"heading": "Preparing for the conversations", "note": "Read back through what you've written. Notice anything that's still vague, and make it more specific. Now, for each person, think through how the conversation should happen. A few principles: - **In person if possible.** Phone is a fine second choice. Video third. Text and email don't carry this kind of conversation. They're too thin. - **Choose the moment.** Not the end of a busy dinner. Not while one of you is rushing somewhere. You want enough time, and quiet enough surroundings, that the conversation can land. - **Open with the small frame, then the big one.** Standard catching-up first. Then, when the small talk starts to wind down, name the bigger thing: *Actually, there's something specific I wanted to talk to you about.* A rough sketch of the arc, not a script: - **The frame.** *I've been doing some real personal work over the past months. I'm coming to the end of it, and I'm thinking about what I want the next chapter to look like.* - **What you've been doing.** Without giving them every detail, share the shape. What you went into the work for. What's shifted. What you're walking out with. - **The ask.** Why you're choosing them specifically. What you appreciate about them. What kind of support you're asking for, in concrete terms. - **The check.** *Is that something you'd be willing to do?* - **The agreement.** If they say yes, get specific about what that actually looks like in practice. When will you check in? How? What does this person have permission to do or say? - **Gratitude.** Thank them, and mean it. This is a real gift you've just been given. You're going to feel exposed. That's appropriate. The exposure is part of the work. People rarely turn down a request like this, partly because the request itself communicates how much you respect them. *Have all three conversations before you complete Part 2.*", "prompts": []}]},
  {"module": 8, "slug": "new-invitation-part-2", "code": "08.04B", "kind": "Journal", "title": "New Invitation Part 2", "blurb": "**What was said?** A short summary of how the conversation actually went. Did it follow the arc you imagined?…", "intro": "Complete this after you've had all three conversations. The conversations themselves were the work. This journal is just to help you metabolize what happened in them. For each ally, answer briefly. A paragraph or two per question is enough.", "sections": [{"heading": "Ally 1", "prompts": [{"id": "new-invitation-part-2-1", "kind": "short", "label": "What was said? A short summary of how the conversation actua", "text": "**What was said?** A short summary of how the conversation actually went. Did it follow the arc you imagined? Where did it surprise you?"}, {"id": "new-invitation-part-2-2", "kind": "long", "label": "What did you notice in your body before, during, and after? ", "text": "**What did you notice in your body before, during, and after?** This is more important than it sounds. The somatic signal often tells you something the conversation itself didn't make explicit."}, {"id": "new-invitation-part-2-3", "kind": "long", "label": "What did they offer that you didn't expect? Often people res", "text": "**What did they offer that you didn't expect?** Often people respond with more than you asked for. Or differently than you asked for. Or something that didn't quite match what you needed but is its own kind of offer."}, {"id": "new-invitation-part-2-4", "kind": "long", "label": "What's the agreement, in one sentence?", "text": "**What's the agreement, in one sentence?**"}]}, {"heading": "Ally 2", "prompts": [{"id": "new-invitation-part-2-5", "kind": "short", "label": "What did you notice in your body before, during, and after?", "text": "**What did you notice in your body before, during, and after?**"}, {"id": "new-invitation-part-2-6", "kind": "long", "label": "What did they offer that you didn't expect?", "text": "**What did they offer that you didn't expect?**"}, {"id": "new-invitation-part-2-7", "kind": "long", "label": "What's the agreement, in one sentence?", "text": "**What's the agreement, in one sentence?**"}]}, {"heading": "Ally 3", "prompts": [{"id": "new-invitation-part-2-8", "kind": "short", "label": "What did you notice in your body before, during, and after?", "text": "**What did you notice in your body before, during, and after?**"}, {"id": "new-invitation-part-2-9", "kind": "long", "label": "What did they offer that you didn't expect?", "text": "**What did they offer that you didn't expect?**"}, {"id": "new-invitation-part-2-10", "kind": "long", "label": "What's the agreement, in one sentence?", "text": "**What's the agreement, in one sentence?**"}]}, {"heading": "Looking across all three", "prompts": [{"id": "new-invitation-part-2-11", "kind": "long", "label": "What did all three conversations have in common? Was there a", "text": "**What did all three conversations have in common?** Was there a theme that came up that you didn't plan to name?"}, {"id": "new-invitation-part-2-12", "kind": "long", "label": "What do you have now that you didn't have before these conve", "text": "**What do you have now that you didn't have before these conversations?** Beyond the specific agreements: how does it feel to have done this? What's different in your relationships, or in your sense of yourself, after?"}, {"id": "new-invitation-part-2-13", "kind": "long", "label": "What's still missing? Are there other people in your life yo", "text": "**What's still missing?** Are there other people in your life you now realize you also want to have this conversation with? Other kinds of support you didn't know you needed until you started asking? Anything you wish you had said and didn't?"}]}]},
  {"module": 8, "slug": "session-prep-8", "code": "08.07", "kind": "Session prep", "title": "Session Prep", "blurb": "In one paragraph, what's the most important thing that has shifted in you over the course of this work? Not…", "intro": "This is the last journal of Mind/Body Foundations. Our final session deserves more than the usual what do you want to talk about? preparation. So this prep is structured. It will take you about thirty to forty-five minutes. Email it to me at chad@herstwellness.com at least 24 hours before our session.", "sections": [{"heading": "1. Looking back", "prompts": [{"id": "session-prep-8-1", "kind": "long", "label": "1. Looking back", "text": "In one paragraph, what's the most important thing that has shifted in you over the course of this work? Not the most articulate or the most impressive thing. The most important. The one you'd most want me to know about as we close."}]}, {"heading": "2. The proudest moment", "prompts": [{"id": "session-prep-8-2", "kind": "long", "label": "2. The proudest moment", "text": "Pick one moment from the last few months that you're proud of. It can be a moment in a meditation, a moment in a hard conversation, a decision you made, a reaction you didn't have. Describe it. What happened, and what made it different from how you would have shown up before this work?"}]}, {"heading": "3. The fear", "prompts": [{"id": "session-prep-8-3", "kind": "long", "label": "3. The fear", "text": "Looking forward into the integration phase, into the next chapter: what scares you? Be honest. Not in the abstract. The specific thing you're worried about. Maybe it's that you'll stop meditating. Maybe it's that you'll go back to a relationship pattern you've been working to change. Maybe it's that the calm you've found will leave you and you won't know how to find it again. This is the question I most want to talk through with you in our last session. Don't skip it."}]}, {"heading": "4. The unfinished", "prompts": [{"id": "session-prep-8-4", "kind": "long", "label": "4. The unfinished", "text": "Is there anything from the work itself, any teaching, framework, or insight, that still feels incomplete or unresolved for you? Anything you wish we'd spent more time on, or that didn't quite land? This is your chance to flag it. Our last hour is yours."}]}, {"heading": "5. The path", "prompts": [{"id": "session-prep-8-5", "kind": "long", "label": "5. The path", "text": "You've read **08.05A What Comes Next**: on your own, a rhythm of check-ins, or ongoing work together. Which way are you leaning, and what does the leaning feel like in your body? A leaning is not a commitment. Nothing gets decided in the room. I want to know where you stand as we walk in, and I'll bring my own honest read of what looks finished and what doesn't."}]}, {"heading": "6. The use of our final session", "prompts": [{"id": "session-prep-8-6", "kind": "long", "label": "6. The use of our final session", "text": "Some possibilities: - **Reflect back across the whole arc.** A retrospective, walking through what you're walking out with. Slower, more spacious. - **Work on the fear (#3 above).** Use the session to specifically work through what scares you about the integration phase, with concrete strategies. - **Work on the unfinished (#4 above).** Spend the time on the teaching or insight that hasn't fully landed. - **Work on a specific challenge.** A live situation in your life right now where you want to bring everything you've learned to bear, with my help. - **Some combination of the above.** Tell me how you'd want it to flow. What feels most valuable to you?"}]}, {"heading": "7. Anything else", "prompts": [{"id": "session-prep-8-7", "kind": "long", "label": "7. Anything else", "text": "Anything you want me to know, or want to ask, that none of the above questions reached? *Send it to me. I'll read it carefully before we meet, and I'll come to our session ready to do exactly what you've asked for.* *See you soon.*"}]}]}
];

const BY_SLUG = new Map(JOURNALS.map((j) => [j.slug, j]));

function findJournal(moduleNumber, slug) {
  const journal = BY_SLUG.get(slug);
  if (!journal || journal.module !== Number(moduleNumber)) return null;
  return journal;
}

function allPrompts(journal) {
  const out = [];
  for (const section of journal.sections) {
    for (const prompt of section.prompts) out.push(prompt);
  }
  return out;
}

function journalsForModule(moduleNumber) {
  return JOURNALS.filter((j) => j.module === Number(moduleNumber));
}

module.exports = { JOURNALS, findJournal, allPrompts, journalsForModule };
